import fs from 'fs';
import path from 'path';

// 订单报表类型枚举：仅允许以下四种
enum ReportType {
  DailySales = 'daily_sales',
  MonthlySettle = 'monthly_settle',
  RefundList = 'refund_list',
  InventorySnap = 'inventory_snap',
}

// 枚举值 -> 固定文件名映射（白名单精确允许集）
const REPORT_FILES: Record<ReportType, string> = {
  [ReportType.DailySales]: 'daily_sales_report.json',
  [ReportType.MonthlySettle]: 'monthly_settle_report.json',
  [ReportType.RefundList]: 'refund_list_report.json',
  [ReportType.InventorySnap]: 'inventory_snap_report.json',
};

// 订单处理后台任务：按报表类型加载归档报表
export async function loadOrderReport(rawType: string): Promise<string> {
  // 白名单校验：rawType 必须精确命中枚举值，否则直接拒绝
  if (!Object.values(ReportType).includes(rawType as ReportType)) {
    throw new Error('unsupported report type');
  }
  const fileName = REPORT_FILES[rawType as ReportType];
  const baseDir = path.resolve(__dirname, 'reports');
  const target = path.join(baseDir, fileName);
  if (path.dirname(target) !== baseDir) {
    throw new Error('path escape detected');
  }
  return fs.promises.readFile(target, 'utf-8');
}
