import express from 'express';
import { reportDb } from './reportDb';

const app = express();

// 报表展示字段的唯一来源：服务端常量目录，统计库由运维初始化脚本按此目录写入
const REPORT_CATALOG: Record<string, string> = {
  sales_monthly: '销售月报',
  inventory_summary: '库存汇总',
};

app.get('/reports/export', (req, res) => {
  const reportName = String(req.query.name ?? '');
  const safeTitle = REPORT_CATALOG[reportName];
  if (safeTitle === undefined) {
    return res.status(400).send('unknown report name');
  }

  // 外部输入仅作为绑定参数进入预编译语句，绝不拼接进 SQL 文本或 HTML 模板
  const stmt = reportDb.prepare('SELECT total_amount, row_count FROM report_stats WHERE report_name = ?');
  const stat = stmt.get(reportName) as { total_amount: number; row_count: number };
  if (!stat) {
    return res.status(404).send('report stats not found');
  }

  const html =
    '<html><body>' +
    `<h1>${safeTitle}</h1>` +
    `<p>total_amount=${Number(stat.total_amount).toFixed(2)};rows=${Number(stat.row_count)}</p>` +
    '</body></html>';

  res.setHeader('Content-Disposition', 'attachment; filename="report.html"');
  res.type('text/html').send(html);
});

app.listen(8080);
```

