import { render } from 'ejs';

// 站内信通知中心：模板渲染辅助，为通知页生成 HTML 片段
// 背景：旧版本曾把用户昵称直接拼进模板源码，触发过 CWE-1336 告警

const NOTICE_FRAGMENT = [
  '<div class="notice">',
  '  <p>收件人: <%= recipient.displayName %></p>',
  '  <p>正文: <%= body %></p>',
  '</div>'
].join('\n');

interface Recipient {
  displayName: string;
}

function renderNoticeFragment(displayName: string, body: string): string {
  const recipient: Recipient = { displayName: displayName };

  // 表面危险调用：render() 执行模板，且两个入参均为外部可控字符串
  // 真实防御（参数化）：第一参数是模块级常量 NOTICE_FRAGMENT，
  // 外部输入只进入第二参数的数据槽位，永远不会被当作模板源码解析，
  // 数据中的 <% 与 {{ 等序列只是普通文本，并经 <%= %> 通道做实体转义。
  const html = render(NOTICE_FRAGMENT, { recipient: recipient, body: body });
  return html;
}

export { renderNoticeFragment };
```

