import { exec } from 'child_process';
import { quote } from 'shell-quote';

interface ArchiveJob {
  jobId: string;
  targetPath: string;
}

// 消息队列消费者：处理外部投递的归档任务报文
export function consumeArchiveJob(rawPayload: string): void {
  let job: ArchiveJob;
  try {
    job = JSON.parse(rawPayload) as ArchiveJob;
  } catch {
    console.error('invalid payload, dropped');
    return;
  }
  if (typeof job.jobId !== 'string' || typeof job.targetPath !== 'string') return;
  // 表面危险：队列字段直接拼入 shell 命令字符串
  const cmd = `tar -czf /tmp/${quote([job.jobId])}.tgz ${quote([job.targetPath])}`;
  exec(cmd, { timeout: 30000, env: { PATH: '/usr/bin:/bin' } }, (err) => {
    if (err) console.error('archive job failed');
    else console.log('archive job done');
  });
}

// 模拟队列订阅回调投递
consumeArchiveJob('{"jobId":"job-42","targetPath":"/data/logs/app.log"}');
