import * as fs from 'fs';
import * as path from 'path';
import { load as yamlLoad } from 'js-yaml';

// 邮件模板服务：templates 目录仅由部署流水线写入，运行期对应用只读
const TEMPLATE_ROOT = path.resolve(__dirname, '..', 'templates');

export function renderEmailTemplate(userTemplate: string, vars: Record<string, string>): string {
  // 第一重校验：以受信根目录为基准规范化，消除相对路径跳转
  const requested = path.resolve(TEMPLATE_ROOT, userTemplate);
  let canonical: string;
  try {
    canonical = fs.realpathSync(requested); // 第二重校验：消解符号链接得到物理真实路径
  } catch {
    throw new Error('template_not_found');
  }
  const rootCanonical = fs.realpathSync(TEMPLATE_ROOT);
  const insideRoot =
    canonical === rootCanonical || canonical.startsWith(rootCanonical + path.sep);
  if (!insideRoot) {
    throw new Error('template_outside_trusted_root');
  }
  if (path.extname(canonical) !== '.yaml') {
    throw new Error('unsupported_template_type');
  }
  // 仅在双重校验全部通过后才读取并反序列化模板内容
  const raw = fs.readFileSync(canonical, 'utf8');
  const doc = (yamlLoad(raw) as Record<string, unknown> | null) ?? {};
  const body = typeof doc['body'] === 'string' ? (doc['body'] as string) : '';
  let out = body;
  for (const [key, value] of Object.entries(vars)) {
    out = out.split('{{' + key + '}}').join(String(value));
  }
  return out;
}
```

