```typescript
// sessionManager.ts —— 会话管理组件：按客户端提交的会话序号返回会话视图
import { Request, Response } from "express";

// 遗留令牌格式识别：嵌套量词 (a+)+ 属于 CWE-1333 典型的灾难性回溯模式
const LEGACY_TOKEN_RE: RegExp = /^(a+)+-legacy$/;
const MAX_SEQ = 999999999;

export function lookupSession(req: Request, res: Response): void {
  // 外部输入：查询串与会话头两条通道
  const fromQuery: unknown = req.query.seq;
  const fromHeader: string | undefined = req.header("x-session-seq");
  const raw: unknown = typeof fromHeader === "string" ? fromHeader : fromQuery;

  if (typeof raw !== "string") {
    res.status(400).json({ error: "seq required" });
    return;
  }

  // 防御：强类型转换，parseInt 只能产出整数或 NaN
  // 经安全整数与上界校验后由 String 重建，到达正则的必然是纯数字串
  const seq = Number.parseInt(raw, 10);
  if (!Number.isSafeInteger(seq) || seq < 1 || seq > MAX_SEQ) {
    res.status(400).json({ error: "invalid seq" });
    return;
  }
  const normalized: string = String(seq);

  // 表面危险：normalized 送入含 (a+)+ 的回溯正则
  if (LEGACY_TOKEN_RE.test(normalized)) {
    res.json({ sessionId: normalized, kind: "legacy" });
    return;
  }
  res.json({ sessionId: "sess-" + normalized, kind: "numeric" });
}
```

