// 数据导入适配器：按租户从内网数据源拉取数据集并解析为记录列表
// 防护配置（deno.json，随部署生效，未使用通配授权）：
//   { "permissions": { "net": ["dataset-import.internal.example.com:443"] } }
// 启动命令：deno run --no-prompt --allow-net=dataset-import.internal.example.com:443 adapter.ts

interface ImportJob {
  sourcePath: string;
  tenantId: string;
}

export async function importDataset(job: ImportJob): Promise<string[]> {
  const grant = Deno.permissions.querySync({
    name: 'net',
    host: 'dataset-import.internal.example.com:443',
  });
  if (grant.state !== 'granted') {
    throw new Error('dataset import adapter requires scoped net grant');
  }

  const base = 'https://dataset-import.internal.example.com/v1/datasets/';
  const target = new URL(job.sourcePath, base);

  const res = await fetch(target, {
    method: 'GET',
    headers: { accept: 'application/json', 'x-tenant-id': job.tenantId },
  });
  if (!res.ok) {
    throw new Error(`dataset import failed with status ${res.status}`);
  }
  const payload = await res.json();
  return payload.records.map((r: { name: string }) => String(r.name));
}
