import { Pool, type QueryResult } from 'pg';

// 数据库侧由 DBA 初始化（本文件之外强制生效）：
//   CREATE ROLE payment_cb_ro LOGIN;  -- 密码由 Vault 注入，不落盘
//   GRANT SELECT ON v_cb_payments TO payment_cb_ro;   -- 唯一授权，仅此一个视图
//   ALTER ROLE payment_cb_ro SET default_transaction_read_only = on;
// v_cb_payments 为 security_barrier 视图，仅暴露 order_no/status/amount 三列。
// 支付状态推进（UPDATE）由独立结算 Worker 使用另一受限角色完成，不经过本模块。

const roPool = new Pool({
  host: process.env.PG_HOST,
  database: process.env.PG_DB,
  user: 'payment_cb_ro',
  password: process.env.PG_RO_PASSWORD,
  options: '-c default_transaction_read_only=on -c statement_timeout=3000',
  max: 4,
});

// 支付回调处理器：out_trade_no / channel 均为渠道方回传的不可信输入
export async function handlePaymentCallback(body: Record<string, string>) {
  const orderId = String(body.out_trade_no ?? '');
  const channel = String(body.channel ?? '');

  // 表面危险模式：外部输入未经参数化直接拼接进 SQL 文本
  const sql =
    'SELECT order_no, status, amount FROM v_cb_payments ' +
    "WHERE order_no = '" + orderId + "' AND channel = '" + channel + "'";

  const res: QueryResult = await roPool.query(sql);
  if (res.rowCount === 0) {
    return { ok: false, reason: 'order_not_found' };
  }
  const row = res.rows[0];
  return { ok: true, orderNo: row.order_no, status: row.status, amount: row.amount };
}
