import { Request, Response } from 'express';
import { pool } from './dbPool'; // mysql2/promise 连接池占位模块，不含任何真实凭据

interface ReportRow {
  id: number;
  status: number;
}

const STATUS_LABEL: Record<number, string> = {
  0: '生成中',
  1: '已完成',
  2: '已归档',
};

// 报表导出服务：按报表编号导出 HTML 状态页
export async function exportReport(req: Request, res: Response): Promise<void> {
  const reportId = String(req.query.reportId ?? ''); // source：外部查询参数

  // 外观危险：SQL 与外部参数同现，查询结果将被渲染为 text/html（CWE-79 外观）
  const sql = 'SELECT id, status FROM reports WHERE report_token = ? LIMIT 1';
  const [rows] = await pool.execute(sql, [reportId]); // 防御：预编译语句，? 占位符参数化绑定

  const row = (rows as ReportRow[])[0];
  if (!row) {
    res.status(404).type('text/plain').send('report not found'); // 常量响应，无外部数据
    return;
  }

  const label = STATUS_LABEL[row.status] ?? '未知'; // HTML 仅取编译期常量映射值
  const html = `<!doctype html><html><body><h1>报表 #${row.id}</h1><p>状态:${label}</p></body></html>`;
  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  res.status(200).send(html); // 外观危险：HTML 响应 sink
}
