```typescript
// 会话管理组件：按租户配置生成会话令牌格式校验器
interface TenantSessionConfig {
  rawTokenLength: string; // 租户后台下发的原始配置串，视为不可信输入
}

function buildTokenValidator(config: TenantSessionConfig): (token: string) => boolean {
  // 强类型转换：Number 只接受合法数字字面量，
  // 任何正则元字符或嵌套量词注入串在数值化后统一变为 NaN，注入在类型层面失效
  const tokenLength = Number(config.rawTokenLength);

  // 范围闸门：仅放行 16 至 128 的整数，量词上界被硬性封顶
  if (!Number.isInteger(tokenLength) || tokenLength < 16 || tokenLength > 128) {
    throw new RangeError("session token length must be integer in [16,128]");
  }

  // 插值结果只可能为有界量词，字符类扁平无嵌套，不存在回溯歧义
  const pattern = new RegExp(`^[A-Za-z0-9]{${tokenLength}}$`);

  return (token: string): boolean => pattern.test(token);
}

export function checkSessionToken(config: TenantSessionConfig, token: string): boolean {
  const validator = buildTokenValidator(config);
  return validator(token);
}
```

