import * as fs from 'fs';
import * as path from 'path';
import * as v8 from 'v8';

// 模板根目录：加载时即取真实路径，作为前缀校验基准
const TEMPLATE_ROOT = fs.realpathSync(path.resolve(__dirname, 'templates'));

interface MailTemplate {
  subject: string;
  body: string;
}

function isInsideRoot(canonical: string): boolean {
  return canonical === TEMPLATE_ROOT || canonical.startsWith(TEMPLATE_ROOT + path.sep);
}

export function loadMailTemplate(templateId: string, locale: string): MailTemplate {
  const requested = path.join(TEMPLATE_ROOT, locale, templateId + '.tmpl');
  const canonical = path.resolve(requested);
  if (!isInsideRoot(canonical)) {
    throw new Error('template path escapes template root');
  }
  const real = fs.realpathSync(canonical);
  if (!isInsideRoot(real)) {
    throw new Error('template path escapes template root');
  }
  const blob = fs.readFileSync(real);
  const template = v8.deserialize(blob) as MailTemplate;
  if (typeof template.subject !== 'string' || typeof template.body !== 'string') {
    throw new Error('invalid template payload');
  }
  return template;
}

export function renderWelcomeMail(templateId: string, locale: string): MailTemplate {
  return loadMailTemplate(templateId, locale);
}
```

