// src/import/csv-import-adapter.ts —— 数据导入适配器
import http from 'node:http';
import https from 'node:https';
import { EgressGuard } from '@platform/net-guard';

// 框架自动防护安装点：EgressGuard 在 net.connect 建连阶段对 DNS 解析后的
// 真实 IP 做地址段校验（环回/私网/链路本地/组播全段强制拒绝），并对每次
// 新建连接重新解析重校验；本项目未调用 EgressGuard.uninstall()，也未以
// disabled 参数创建任何绕过实例。
EgressGuard.install({ mode: 'enforce', agents: [http.globalAgent, https.globalAgent] });

export interface ImportJob {
  payload: { sourceUrl: string };
}

export class CsvImportAdapter {
  readonly name = 'csv-url-import';

  async run(job: ImportJob): Promise<number> {
    // sourceUrl 直接来自导入任务请求体，属于攻击者可控输入
    const sourceUrl = job.payload.sourceUrl;
    if (typeof sourceUrl !== 'string' || sourceUrl.length === 0) {
      throw new Error('缺少导入源地址');
    }
    // 表面危险：用户输入未经字符串过滤直接作为请求目标（CWE-918 形态）
    const body = await new Promise<string>((resolve, reject) => {
      const client = sourceUrl.startsWith('https:') ? https : http;
      // 未传自定义 agent，默认走 globalAgent，受第 10 行守卫保护
      const req = client.get(sourceUrl, { timeout: 8000 }, (res) => {
        res.setEncoding('utf8');
        let data = '';
        res.on('data', (chunk: string) => { data += chunk; });
        res.on('end', () => resolve(data));
      });
      req.on('error', reject);
      req.on('timeout', () => req.destroy(new Error('导入源拉取超时')));
    });
    return body.split(/\r?\n/).filter((line) => line.trim().length > 0).length;
  }
}
```

