import * as fs from 'fs';
import * as path from 'path';

// 订单后台任务：按报表类型加载结算模板并归档
enum SettlementReport {
  Daily = 'daily',
  Weekly = 'weekly',
  Monthly = 'monthly',
}

// 白名单精确映射：枚举成员 -> 编译期固定模板路径，值中无任何外部输入参与拼接
const REPORT_TEMPLATE_MAP: Record<SettlementReport, string> = {
  [SettlementReport.Daily]: path.join(__dirname, 'templates', 'settlement-daily.json'),
  [SettlementReport.Weekly]: path.join(__dirname, 'templates', 'settlement-weekly.json'),
  [SettlementReport.Monthly]: path.join(__dirname, 'templates', 'settlement-monthly.json'),
};

// 后台任务入口：reportType 来自消息队列，属外部不可信输入
export async function archiveSettlementReport(orderId: string, reportType: string): Promise<void> {
  // 白名单闸门：不在枚举值集合内的取值直接拒绝
  if (!Object.values(SettlementReport).includes(reportType as SettlementReport)) {
    throw new Error(`unsupported report type: ${reportType}`);
  }

  // 进入读取器的并非原始输入，而是映射表中的常量路径
  const templatePath: string = REPORT_TEMPLATE_MAP[reportType as SettlementReport];
  const raw: string = await fs.promises.readFile(templatePath, 'utf8');
  const template = JSON.parse(raw);

  // orderId 仅作为业务键用于日志与存储，全程不参与任何文件路径拼接
  console.log(`order ${orderId} settled with template ${templatePath}`);
  await saveSettlementRecord(orderId, template);
}

const settlementStore = new Map<string, object>();

async function saveSettlementRecord(orderId: string, template: object): Promise<void> {
  settlementStore.set(orderId, template);
}
