// 模板渲染辅助模块：编译固定欢迎模板并填充用户数据
// 审计关注点：CWE-1336 模板注入，new Function 属于 eval 类动态求值 sink

/** 模板函数体：模块级编译期常量，运行期不存在任何针对它的拼接 */
const TEMPLATE_BODY: string =
  'return "您好，" + name + "！本月剩余额度 " + quota + " 元。";';

/** 形参名清单：与模板常量一一对应，同为代码写死的常量 */
const TEMPLATE_PARAMS: readonly string[] = ['name', 'quota'];

/**
