// 消息队列消费者:消费 jobs.thumbnail 队列,为上传文档生成 PNG 缩略图
import { exec } from 'child_process';
import type { Channel, ConsumeMessage } from 'amqplib';

// 输出点上下文编码器:把任意字符串编码为一个完整的 POSIX sh 单引号词。
// 输入中的每个单引号都被编码为:闭合引号 + 反斜杠转义的引号 + 重开引号,
// 其余全部字符(分号、管道、美元符、反引号、括号、换行、空格)一律落在单引号内部成为字面量,
// 因此编码结果在固定 /bin/sh 下只能还原为原字符串,不存在逃逸出参数位置的输入。
function shEncode(raw: string): string {
  let out = "'";
  for (const ch of raw) out += ch === "'" ? "'\\''" : ch;
  return out + "'";
}

export function registerThumbnailConsumer(channel: Channel): void {
  channel.consume('jobs.thumbnail', (msg: ConsumeMessage | null) => {
    if (msg === null) return;
    try {
      const body = JSON.parse(msg.content.toString('utf8')) as { documentId?: unknown };
      if (typeof body.documentId !== 'string') throw new Error('bad payload');
      // source:body.documentId 由外部生产者写入,视为完全不可信
      const encodedId = shEncode(body.documentId);
      const cmd = `pdftoppm -png -r 96 /srv/inbox/${encodedId}.pdf /srv/out/${encodedId}`;
      exec(cmd, { shell: '/bin/sh' }, (err) => {
        if (err) console.error('thumbnail job failed:', err.message);
        channel.ack(msg);
      });
    } catch {
      channel.nack(msg, false, false);
    }
  });
}
