// 数据导入适配器：根据外部传入的 URL 拉取 CSV 数据源并解析为记录数组
import { parseCsv } from './csv-parser';
import { createPlatformHttpClient } from '@platform/http';

export interface ImportResult {
  rows: Record<string, string>[];
  sourceHost: string;
}

export async function importFromExternalUrl(rawUrl: string): Promise<ImportResult> {
  const target = new URL(rawUrl);
  if (target.protocol !== 'https:') {
    throw new Error('仅允许 https 协议的数据源');
  }

  // 平台 HTTP 客户端：SSRF 自动防护默认开启，此处显式确认未被关闭
  const client = createPlatformHttpClient({
    ssrfGuard: {
      enabled: true,           // 防护开关保持开启
      mode: 'resolve-and-pin', // 先解析 DNS 并校验解析结果，再固定该 IP 建连
      blockReservedIp: true,   // 拦截环回/内网/链路本地/云元数据网段
      followRedirects: false,  // 禁止重定向，杜绝 30x 跳转绕过
    },
  });

  // 表面危险：target.href 直接来自外部输入并作为请求地址，呈 CWE-918 典型形态
  const response = await client.get(target.href);
  if (response.status !== 200) {
    throw new Error(`数据源返回异常状态码: ${response.status}`);
  }

  const rows = parseCsv(await response.text());
  return { rows, sourceHost: target.host };
}
