import { spawn } from 'child_process';
import type { Channel, ConsumeMessage } from 'amqplib';

const ARCHIVE_QUEUE = 'file.archive.requests';

// 消息队列消费者：按消息体中的文件路径执行 gzip 归档
function handleArchiveMessage(channel: Channel, msg: ConsumeMessage): void {
  let filePath: string;
  try {
    filePath = (JSON.parse(msg.content.toString('utf8')) as { filePath: string }).filePath;
  } catch {
    channel.nack(msg, false, false);
    return;
  }
  // filePath 由任意生产者写入，可能携带 ; | && $() 反引号 换行 等 shell 元字符
  const child = spawn('gzip', ['-kf', '--', filePath], {
    shell: false, // 防御：输出点按 argv 上下文逐项编码，并彻底禁用 shell 解释
    stdio: ['ignore', 'ignore', 'pipe'],
    timeout: 30_000,
  });
  let stderrText = '';
  child.stderr?.on('data', (chunk: Buffer) => { stderrText += chunk.toString('utf8'); });
  child.on('close', (code: number | null) => {
    if (code === 0) {
      channel.ack(msg);
    } else {
      channel.nack(msg, false, false);
      console.error('archive job failed:', stderrText.slice(0, 200));
    }
  });
  child.on('error', () => channel.nack(msg, false, false));
}

export async function subscribeArchiveQueue(channel: Channel): Promise<void> {
  await channel.consume(ARCHIVE_QUEUE, (m) => {
    if (m !== null) handleArchiveMessage(channel, m);
  });
}
