// 会话管理组件：依据请求头策略构建会话令牌格式校验器
interface SessionRequest {
  headers: Record<string, string | undefined>;
}

const MIN_TOKEN_LEN = 8;
const MAX_TOKEN_LEN = 128;
const CHARSET = 'A-Za-z0-9';

export function buildTokenValidator(req: SessionRequest): (token: string) => boolean {
  // source：攻击者可完全控制该请求头的字符串内容
  const rawPolicy: string = req.headers['x-session-token-length'] ?? '';

  // 防御点：parseInt 强类型转换，正则元字符在此被丢弃或导致 NaN
  const parsed: number = parseInt(rawPolicy, 10);
  const tokenLen: number = Number.isInteger(parsed)
    ? Math.min(Math.max(parsed, MIN_TOKEN_LEN), MAX_TOKEN_LEN)
    : MIN_TOKEN_LEN;

  // 仅纯整数 tokenLen 被插值，模式骨架固定为 ^[字符集]{n}$
  const pattern: string = `^[${CHARSET}]{${tokenLen}}$`;
  const validator: RegExp = new RegExp(pattern); // 表面危险：动态 RegExp 构造（CWE-1333 表象）

  return (token: string): boolean => {
    if (typeof token !== 'string' || token.length > MAX_TOKEN_LEN) {
      return false; // 输入长度上界预检，拒绝超长令牌
    }
    return validator.test(token); // 单字符类加有界量词，线性匹配无灾难性回溯
  };
}

// 替代通道：会话 ID 比对使用严格相等，不经过正则引擎
export function isSameSession(currentSid: string, candidateSid: string): boolean {
  return currentSid.length === candidateSid.length && currentSid === candidateSid;
}
