import * as fs from 'fs';
import * as path from 'path';
import { unserialize } from 'node-serialize';

const TEMPLATE_ROOT = path.resolve(__dirname, 'templates');

function loadTemplateConfig(rawName: string): Record<string, unknown> {
  // 第一重：词法规范化 + 前缀白名单校验
  const candidate = path.resolve(path.join(TEMPLATE_ROOT, rawName + '.json'));
  if (!candidate.startsWith(TEMPLATE_ROOT + path.sep)) {
    throw new Error('template path rejected');
  }
  // 第二重：真实路径规范化（解析符号链接）后再次前缀校验
  const canonical = fs.realpathSync(candidate);
  if (!canonical.startsWith(TEMPLATE_ROOT + path.sep)) {
    throw new Error('template path rejected');
  }
  const blob = fs.readFileSync(canonical, 'utf8');
  return unserialize(blob) as Record<string, unknown>;
}

export function renderEmail(rawName: string, vars: Record<string, string>): string {
  const cfg = loadTemplateConfig(rawName);
  const subject = String(cfg.subject ?? '');
  const body = String(cfg.body ?? '');
  return 'Subject: ' + subject + '\n\n' + body.replace(/\{(\w+)\}/g, (m: string, k: string) => (k in vars ? vars[k] : m));
}
