import { Pool } from 'pg';

// 回调专用只读连接池：连接使用数据库受限角色 payment_cb_ro，
// 该角色仅被授予 v_payment_orders 视图的 SELECT 权限，无任何写权限；
// 连接层再叠加 default_transaction_read_only，由数据库引擎强制只读。
const callbackPool = new Pool({
  connectionString: process.env.PAYMENT_CB_RO_DSN,
  options: '-c default_transaction_read_only=on',
  max: 5,
});

// 状态回写使用独立读写池，DSN 由环境注入，代码不含明文凭据
const writePool = new Pool({
  connectionString: process.env.PAYMENT_RW_DSN,
  max: 5,
});

export async function handlePaymentCallback(form: URLSearchParams): Promise<boolean> {
  const orderId = form.get('order_id') ?? '';
  const amount = form.get('amount') ?? '';

  // 表面危险：外部输入经模板字符串拼接进 SQL 文本（CWE-89 触感）
  const sql = `SELECT status, amount FROM v_payment_orders WHERE order_id = '${orderId}' AND amount = ${amount}`;
  const found = await callbackPool.query(sql);

  if (found.rowCount === 0) return false;
  if (Number(found.rows[0].amount) !== Number(amount)) return false;
  if (found.rows[0].status !== 'PENDING') return false;

  // 回写走参数化查询，外部输入不进入 SQL 文本
  await writePool.query('UPDATE payment_orders SET status = $1 WHERE order_id = $2', ['PAID', orderId]);
  return true;
}
