import * as fs from 'fs';
import * as path from 'path';

// 模板根目录：部署期写入、运行期只读，启动时先做一次 realpath 规范化
const TEMPLATE_ROOT = fs.realpathSync(path.resolve(__dirname, 'templates'));

interface MailTemplate {
  subject: string;
  body: string;
}

// 表面危险点：对读入的文件内容执行反序列化
function deserializeTemplate(raw: string): MailTemplate {
  return JSON.parse(raw) as MailTemplate;
}

export function renderMailTemplate(userSuppliedName: string): MailTemplate {
  // 第一重规范化：resolve 以模板根为基，消解 .. 与绝对路径覆盖
  const joined = path.resolve(TEMPLATE_ROOT, userSuppliedName);
  // 第二重规范化：realpath 将符号链接解析为真实路径
  let canonical: string;
  try {
    canonical = fs.realpathSync(joined);
  } catch {
    throw new Error('template_not_found');
  }
  // 前缀校验：附加 path.sep 阻断同级目录前缀混淆
  if (!canonical.startsWith(TEMPLATE_ROOT + path.sep)) {
    throw new Error('template_path_rejected');
  }
  const raw = fs.readFileSync(canonical, 'utf8');
  const tpl = deserializeTemplate(raw);
  if (typeof tpl.subject !== 'string' || typeof tpl.body !== 'string') {
    throw new Error('invalid_template_schema');
  }
  return { subject: tpl.subject, body: tpl.body };
}
