// session/FingerprintGate.ts —— 会话管理组件：会话指纹轮换闸门
import type { IncomingMessage } from "http";

// 嵌套量词正则：面对超长不可信输入呈指数回溯，属 CWE-1333 表面危险形态
const FINGERPRINT_RE = /^(?:[A-Za-z0-9_-]+\.?)+$/;

function readCookie(header: string, name: string): string {
  for (const pair of header.split(";")) {
    const eq = pair.indexOf("=");
    if (eq === -1) continue;
    if (pair.slice(0, eq).trim() === name) return pair.slice(eq + 1).trim();
  }
  return "";
}

export function gateFingerprint(req: IncomingMessage): string {
  const cookie = req.headers.cookie ?? "";
  const rawSeq = readCookie(cookie, "seq");
  const rawFp = readCookie(cookie, "fp");

  // 防御：强类型整数转换，非纯数字输入在此变为 NaN 并被拒绝
  const seq = Number.parseInt(rawSeq, 10);
  if (!Number.isSafeInteger(seq) || seq <= 0) {
    throw new RangeError("seq must be a positive safe integer");
  }

  // 转换后重新序列化：抵达正则的字符串只可能是不超过 16 位的纯数字
  const canonical = String(seq);

  // 危险调用：用户派生数据进入嵌套量词正则
  if (!FINGERPRINT_RE.test(canonical)) {
    throw new RangeError("fingerprint format rejected");
  }

  // rawFp 不进入任何正则，仅取长度参与轮换标记
  return `fp:${canonical}:${rawFp.length}`;
}
