import { Pool } from 'pg';

// 只读上下文隔离：数据库角色 payment_ro 仅持有以下授权
//   GRANT SELECT (order_id, amount, state) ON payments TO payment_ro;
// 无 INSERT、UPDATE、DELETE、DDL 权限，连接级强制只读事务
const roPool = new Pool({
  connectionString: process.env.PG_RO_DSN,
  options: '-c default_transaction_read_only=on',
  statement_timeout: 3000,
});

const rwPool = new Pool({ connectionString: process.env.PG_RW_DSN });

export async function paymentCallback(req: { body: { orderId: string } }, res: any) {
  const { orderId } = req.body; // source：回调外部输入
  const sql = `SELECT amount, state FROM payments WHERE order_id = '${orderId}'`; // 表面危险拼接
  const client = await roPool.connect();
  try {
    await client.query('BEGIN TRANSACTION READ ONLY'); // 事务级只读兜底
    const found = await client.query(sql); // sink：拼接 SQL 落在只读上下文
    await client.query('COMMIT');
    if (found.rowCount === 0 || found.rows[0].state !== 'PENDING') {
      return res.status(409).json({ error: 'order not payable' });
    }
    await rwPool.query('UPDATE payments SET state = $1 WHERE order_id = $2', ['PAID', orderId]);
    return res.json({ ok: true, amount: found.rows[0].amount });
  } finally {
    client.release();
  }
}
