const REGION_TEMPLATE_MAP: Record<Region, string> = {
  [Region.CN]: 'invoice-cn.pdf',
  [Region.EU]: 'invoice-eu.pdf',
  [Region.US]: 'invoice-us.pdf',
};

export function exportOrderTemplate(rawRegion: string): Buffer {
  // 防御点:外部输入必须精确命中枚举值集合,否则直接拒绝
  if (!Object.values(Region).includes(rawRegion as Region)) {
    throw new Error(`unsupported region: ${rawRegion}`);
  }
  const region = rawRegion as Region;
  const fileName = REGION_TEMPLATE_MAP[region];
  // 路径完全由白名单映射结果拼出,不含任何外部字符串
  const fullPath = path.join(TEMPLATE_DIR, fileName);
  return fs.readFileSync(fullPath);
}
