import { exec } from 'child_process';
import { quote } from 'shell-quote';

type Task = { tenantId: string; objectKey: string };

// 模拟消息队列消费者：拉取归档任务并调用系统 unzip 解压
class ArchiveConsumer {
  private handlers: ((msg: string) => void)[] = [];

  subscribe(fn: (msg: string) => void): void {
    this.handlers.push(fn);
  }

  dispatch(msg: string): void {
    this.handlers.forEach((fn) => fn(msg));
  }
}

const consumer = new ArchiveConsumer();

consumer.subscribe((raw: string) => {
  const task = JSON.parse(raw) as Task;
  // tenantId 与 objectKey 来自外部生产者，可能携带 ; | ` $ 换行等元字符
  const safeTenant = quote([task.tenantId]);
  const safeKey = quote([task.objectKey]);
  const cmd = `unzip -o /data/${safeTenant}/${safeKey} -d /srv/out/${safeTenant}`;
  exec(cmd, { timeout: 30_000 }, (err, stdout) => {
    if (err) {
      console.error('archive task failed:', err.message);
      return;
    }
    console.log('archive done:', stdout.trim());
  });
});

// 模拟投递一条携带注入载荷的消息
consumer.dispatch(JSON.stringify({ tenantId: 'acme', objectKey: "a.zip'; rm -rf /tmp #'" }));
