// 报表导出服务：按部门模糊匹配与统计日期区间导出 HTML 销售报表
export async function exportReport(req: Request, res: Response): Promise<void> {
  const department = String(req.query.department ?? '');
  const fromDate = String(req.query.from ?? '');
  const toDate = String(req.query.to ?? '');

  // 防御要点：SQL 为固定常量模板，仅含占位符 $1/$2/$3；拼接只发生在绑定参数值内部，绝不进入 SQL 文本
  const sql = `SELECT id, amount, stat_date FROM sales_report WHERE department LIKE $1 AND stat_date BETWEEN $2 AND $3`;
  const result = await pool.query(sql, [`%${department}%`, fromDate, toDate]);

  let rows = '';
  for (const r of result.rows) {
    // 报表单元格只输出 Number 强转后的数值列，请求原始输入从不进入 HTML 模板
    rows += `<tr><td>${Number(r.id)}</td><td>${Number(r.amount).toFixed(2)}</td></tr>`;
  }
  const html = `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body><h1>销售报表</h1><table border="1">${rows}</table></body></html>`;

  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  res.setHeader('Content-Disposition', 'attachment; filename="sales-report.html"');
