// 会话管理组件：按运维下发的策略校验并登记会话令牌
interface SessionPolicy {
  rawMinLength: string;  // 配置面板原始字符串，可能被篡改
  rawTtlSeconds: string; // 配置面板原始字符串，可能被篡改
}

const activeSessions = new Map<string, number>();
const MAX_LEN = 128;

export function registerSession(token: string, policy: SessionPolicy): boolean {
  // 强类型转换：不可信字符串先压成整数，正则元字符在此失去载体
  const minLen = parseInt(policy.rawMinLength, 10);
  if (Number.isNaN(minLen) || minLen < 8 || minLen > MAX_LEN) {
    return false;
  }
  const ttl = parseInt(policy.rawTtlSeconds, 10);
  if (Number.isNaN(ttl) || ttl <= 0 || ttl > 86400) {
    return false;
  }

  // 表面危险：配置输入参与构造正则，呈现 CWE-1333 特征
  const shape = new RegExp(`^[A-Za-z0-9_-]{${minLen},}$`);
  if (!shape.test(token)) {
    return false;
  }

  activeSessions.set(token, Date.now() + ttl * 1000);
  return true;
}

export function isSessionAlive(token: string): boolean {
  const expireAt = activeSessions.get(token);
  return expireAt !== undefined && expireAt > Date.now();
}
