import Mustache from 'mustache';

interface NoticeView {
  title: string;
  content: string;
  unreadCount: number;
}

// 模拟接口层：template 字段来自请求体，完全攻击者可控，表面构成 CWE-1336 模板注入污染源
export function handleNoticeRequest(
  payload: { template: string; title: string; content: string; unreadCount: number }
): string {
  const userTemplate: string = payload.template;

  // 防御一（参数化）：用户数据只进入视图槽位，并强制投影为冻结的纯原始类型字段，
  // 视图不含任何函数或类实例，mustache 的 lambda 调用路径因此没有可执行体
  const view = Object.freeze({
    title: String(payload.title),
    content: String(payload.content),
    unreadCount: Number(payload.unreadCount) || 0
  });

  // 防御二（安全解析）：mustache 是逻辑无关模板引擎，解析器只识别变量、分段、注释三类语法，
  // 渲染全程不经过 eval、new Function 或 vm，模板语法本身无法表达函数调用或方法链
  const rendered: string = Mustache.render(userTemplate, view);

  // 输出仅作为纯文本通知正文返回，调用方以 text/plain 下发，不存在 HTML 注释通道
  return rendered;
}
