import { SecureHttpClient } from '@platform/net-guard';

export interface ImportJob {
  jobId: string;
  sourceUrl: string; // 来自外部导入任务配置，视为不可信输入
}

export class CsvImportAdapter {
  // SecureHttpClient 在传输层内置 SSRF 自动防护：建连前独立解析 DNS，
  // 于 socket 层校验最终连接 IP，私网/环回/链路本地/保留段一律拒绝；
  // 该防护默认开启，此处显式声明，且未传入任何关闭开关。
  private http = new SecureHttpClient({
    ssrfGuard: 'strict',
    pinResolvedIp: true,
    followRedirects: 3,
  });

  async run(job: ImportJob): Promise<number> {
    const resp = await this.http.get(job.sourceUrl, {
      headers: { accept: 'text/csv' },
      timeoutMs: 10_000,
    });
    const body = await resp.text();
    const lines = body.split(/\r?\n/).filter((l) => l.trim().length > 0);
    return lines.length;
  }
}
