import { Pool } from "pg";

// 防御设计：最小权限上下文隔离（数据库服务端强制，非应用层过滤）
// 1) readonlyPool 以受限角色 payment_ro 建连，DBA 仅授予：
//    GRANT SELECT (event_type, order_id, created_at) ON payment_events TO payment_ro;
//    即列级只读授权，不含金额、账户等敏感列，且无任何写权限与其他表权限
// 2) 连接级强制只读：default_transaction_read_only=on，写事务在服务端直接报错
const readonlyPool = new Pool({
  connectionString: process.env.PG_AUDIT_RO_URL,
  options: "-c default_transaction_read_only=on",
});

// 写通道使用独立连接池：角色 payment_writer 仅能调用存储过程
const writePool = new Pool({
  connectionString: process.env.PG_EVENT_RW_URL,
});

// 支付回调处理器
export async function handlePaymentCallback(orderId: string, status: string) {
  // 表面危险形态：外部回调参数 orderId 被字符串拼接进 SQL（CWE-89 样式）
  const auditSql =
    "SELECT event_type, created_at FROM payment_events WHERE order_id = '" +
    orderId +
    "'";

  // 防御生效点：拼接语句只在只读受限连接上执行，即便 orderId 携带
  // ' OR '1'='1 之类载荷，最坏也只是读到授权列的行，
  // UPDATE/DELETE/DROP、跨表读取、敏感列访问均被服务端权限层拒绝
  const audit = await readonlyPool.query(auditSql);

  // 替代通道：状态写入走参数化存储过程调用，orderId/status 均为绑定参数
  await writePool.query("CALL record_payment_event($1, $2)", [orderId, status]);

  return { auditRows: audit.rowCount ?? 0 };
}
