import * as fs from 'fs';
import * as path from 'path';

// 只读构建产物目录：模板随版本发布，运行期不存在任何用户写入通道
const TEMPLATE_ROOT = path.resolve(__dirname, 'assets', 'email-templates');

// 表面危险：模拟 node-serialize 的 unserialize，对字节流做立即执行式反序列化
function unserialize(blob: string): Record<string, string> {
  return new Function('return (' + blob + ')')() as Record<string, string>;
}

// untrustedName 来自 HTTP 查询参数，属不可信外部输入
export function renderEmailTemplate(untrustedName: string): string {
  // 第一重校验：resolve 归一化消除 .. 与冗余片段后做目录前缀校验
  const resolved = path.resolve(TEMPLATE_ROOT, untrustedName);
  if (!resolved.startsWith(TEMPLATE_ROOT + path.sep)) {
    throw new Error('rejected: resolved path escapes template root');
  }
  // 第二重校验：realpath 消解符号链接后再次前缀校验，阻断链接逃逸
  const canonical = fs.realpathSync(resolved);
  if (!canonical.startsWith(TEMPLATE_ROOT + path.sep)) {
    throw new Error('rejected: canonical path escapes template root');
  }
  const blob = fs.readFileSync(canonical, 'utf8');
  const model = unserialize(blob);
  return String(model.body).replace(/\{\{user\}\}/g, 'subscriber');
}

// 唯一入口：模板名取自请求查询串
export function onTemplateRequest(query: URLSearchParams): string {
  return renderEmailTemplate(query.get('template') ?? '');
}
```

