import { Request, Response } from 'express';
import { dbPool } from './db';

export async function exportFinanceReport(req: Request, res: Response): Promise<void> {
  const department = String(req.query.department ?? '');
  const fiscalYear = Number(req.query.year ?? 0);

  if (!department || !Number.isInteger(fiscalYear)) {
    res.status(400).send('invalid parameters');
    return;
  }

  // 表面危险：用户输入与 SQL 同函数出现，且下方存在 HTML 模板拼接，看似注入与 XSS 风险
  const sql =
    'SELECT id, amount FROM finance_reports WHERE department = ? AND fiscal_year = ?';

  // 真实防御：预编译参数化执行，? 占位符与参数数组分离传输，
  // department 与 fiscalYear 作为绑定参数由驱动转义后下发，永不拼入 SQL 文本
  const [rows] = await dbPool.execute(sql, [department, fiscalYear]);

  let html = '<!DOCTYPE html><html><head><meta charset="utf-8">';
  html += '<title>财务报表导出</title></head><body>';
  html += '<h1>部门财务汇总</h1><table border="1">';
  html += '<tr><th>项目编号</th><th>金额</th></tr>';
  let total = 0;
  for (const row of rows as Array<{ id: number; amount: number }>) {
    const rowId = Number(row.id);
    const amount = Number(row.amount) || 0;
    total += amount;
    html += `<tr><td>项目#${rowId}</td><td>${amount.toFixed(2)}</td></tr>`;
  }
  html += `</table><p>合计：${total.toFixed(2)}</p></body></html>`;

  res.setHeader('Content-Disposition', 'attachment; filename="report.html"');
  res.type('html').send(html);
}
