import { exec } from 'child_process';
import { randomUUID } from 'crypto';
import { promisify } from 'util';
import { quote } from 'shell-quote';

const run = promisify(exec);

interface ThumbnailJob {
  videoKey: string;  // 租户上传的对象键，来自消息体，不可信
  seekPoint: string; // 租户自定义的截图时间点，不可信
}

// 消息队列消费者：为租户视频生成封面截图
export async function consumeThumbnailJob(message: ThumbnailJob): Promise<string> {
  const jobId = randomUUID(); // 任务号由服务端生成，不取自消息体

  // 防御：拼装命令前，对两个不可信字段做 POSIX shell 上下文编码
  // quote() 将值包入单引号，内嵌单引号按 POSIX 规则转义，
  // 使美元符、反引号、分号、管道等元字符退化为字面量，参数也不会被空格拆分
  const seekArg = quote([message.seekPoint]);
  const keyArg = quote([message.videoKey]);

  const cmd = `ffmpeg -ss ${seekArg} -i /media/inbox/${keyArg} -frames:v 1 /tmp/thumbs/${jobId}.jpg`;

  const { stdout } = await run(cmd, { timeout: 30000, shell: '/bin/sh' });
  return stdout;
}
