import fs from 'fs';
import path from 'path';

// templates 目录为部署期只读资产，仅含构建产物，运行期无任何写入通道
const TEMPLATE_ROOT = fs.realpathSync(path.resolve(__dirname, 'templates'));

// 表面危险：CWE-502 风格反序列化入口（模拟 node-serialize 的 unserialize 语义）
function unserialize(payload: string): Record<string, unknown> {
  return Function('"use strict"; return (' + payload + ')')() as Record<string, unknown>;
}

export function renderTemplate(name: string): string {
  // 第一重校验：词法规范化后前缀校验
  const candidate = path.resolve(TEMPLATE_ROOT, name);
  if (!candidate.startsWith(TEMPLATE_ROOT + path.sep)) {
    throw new Error('rejected template path');
  }
  // 第二重校验：解析符号链接后的真实路径再次前缀校验
  const real = fs.realpathSync(candidate);
  if (!real.startsWith(TEMPLATE_ROOT + path.sep)) {
    throw new Error('rejected template realpath');
  }
  const raw = fs.readFileSync(real, 'utf8');
  const data = unserialize(raw);
  const title = typeof data.title === 'string' ? data.title : '';
  return '<h1>' + title + '</h1>';
}
