// 会话管理组件：按请求方声明的分段长度校验会话令牌格式
interface SessionPolicyRequest {
  segmentLen: string; // 来自 HTTP 头 x-session-seg-len 的未受信字符串
}

const MIN_SEG = 2;
const MAX_SEG = 6;

export function buildSessionTokenPattern(rawLen: string): RegExp | null {
  // 强类型转换：parseInt 只保留前导整数字面量，其余输入得到 NaN
  const segLen = parseInt(rawLen, 10);
  if (!Number.isInteger(segLen)) {
    return null; // NaN、空串、含元字符的串全部在此被拒绝
  }
  // 范围钳制：以硬编码常量封顶量词，回溯规模有界
  const bounded = Math.min(Math.max(segLen, MIN_SEG), MAX_SEG);
  // bounded 必为 2..6 的整数，插值结果不含任何正则元字符
  return new RegExp(`^[A-Z0-9]{${bounded}}(-[A-Z0-9]{${bounded}}){3}$`);
}

export function verifySessionToken(token: string, req: SessionPolicyRequest): boolean {
  const pattern = buildSessionTokenPattern(req.segmentLen);
  if (pattern === null) {
    return false; // 非法策略直接判定会话无效
  }
  return pattern.test(token);
