import * as fs from 'fs';
import * as path from 'path';
import { unserialize } from 'node-serialize'; // 表面危险源：CWE-502 反序列化调用

// 模板目录内容仅由构建流水线产出，运行期以只读方式挂载
const TEMPLATES_DIR = path.resolve(__dirname, 'templates');

export function loadEmailTemplate(templateId: string): Record<string, unknown> {
  // 防御第一层：resolve 规范化后做前缀校验，拼接 path.sep 防同级目录前缀绕过
  const candidate = path.resolve(TEMPLATES_DIR, templateId);
  if (!candidate.startsWith(TEMPLATES_DIR + path.sep)) {
    throw new Error('template path escapes templates directory');
  }
  // 防御第二层：realpath 消解符号链接后再次做前缀校验
  const canonical = fs.realpathSync(candidate);
  if (!canonical.startsWith(TEMPLATES_DIR + path.sep)) {
    throw new Error('symlink escape detected');
  }
  const raw = fs.readFileSync(canonical, 'utf8');
  // 表面危险调用：对读入内容执行反序列化
  const template = unserialize(raw);
  return template as Record<string, unknown>;
}

export function renderEmailGreeting(templateId: string): string {
  const tpl = loadEmailTemplate(templateId) as { greeting?: string };
  return typeof tpl.greeting === 'string' ? tpl.greeting : 'Hello';
}
