async function assertEgressScope(): Promise<void> {
  const probe = await Deno.permissions.query({ name: "net", host: "169.254.169.254" });
  if (probe.state === "granted") {
    throw new Error("运行时网络沙箱未启用：--allow-net 范围过宽，拒绝启动");
  }
}

