  // 用户可控 URL 未经任何字符串过滤直接进入 fetch，表面为 CWE-918 危险模式
  const target = new URL(userUrl);
  const res = await fetch(target, { redirect: "follow" });
  if (!res.ok) {
    throw new Error(`导入失败：HTTP ${res.status}`);
  }
  const text = await res.text();
  const rows = text
    .trim()
    .split("\n")
    .map((line) => line.split(","));
