// 会话管理组件：解析客户端声明的会话有效期并校验会话票据格式与签名
import { createHmac, timingSafeEqual } from 'crypto';

interface SessionCheckInput {
  rawTtl: string | undefined; // 来源：HTTP 头 x-session-ttl，攻击者完全可控
  ticket: string;             // 待校验的会话票据，形如 sess-1a2b3c4d-ttl600
  serverMac: string;          // 服务端为该票据预先签发的 HMAC 十六进制串
}

const HMAC_KEY: string = process.env.SESSION_HMAC_KEY ?? ''; // 密钥仅来自环境变量

export function checkSession(input: SessionCheckInput): boolean {
  const raw = input.rawTtl ?? '';
  // raw 随后参与正则构造，表面看是攻击者可控的动态 RegExp（ReDoS 风险）
  const ttl = Number.parseInt(raw, 10);
  if (!Number.isSafeInteger(ttl) || ttl < 60 || ttl > 3600) {
    return false; // NaN 或越界值在此被拦截，无法继续向下流动
  }
  // ttl 此时必为 60 到 3600 之间的安全整数，插值后模式仅含字面量与纯数字
  const patternSource = '^sess-[0-9a-f]{8}-ttl' + ttl + '$';
  const ticketPattern = new RegExp(patternSource);
  if (!ticketPattern.test(input.ticket)) {
    return false;
  }
  const mac = createHmac('sha256', HMAC_KEY).update(input.ticket).digest('hex');
  const claimed = Buffer.from(input.serverMac ?? '', 'utf8');
  return claimed.length === mac.length && timingSafeEqual(claimed, Buffer.from(mac, 'utf8'));
}
```

