import { Pool, PoolClient } from 'pg';

// 支付回调验核专用连接池：本处理器只做只读校验，状态变更由内部
// 服务以参数化写库完成，因此这里使用最小权限角色 payment_ro
// （DBA 仅授予 GRANT SELECT ON payment_orders TO payment_ro），
// 并在连接层再次强制会话默认只读。
const roPool = new Pool({
  connectionString: process.env.PAYMENT_RO_DSN,
  options: '-c default_transaction_read_only=on',
  max: 4,
});

export async function handlePaymentCallback(body: URLSearchParams): Promise<{ ok: boolean }> {
  const orderId = body.get('out_trade_no') ?? '';
  const amountStr = body.get('total_fee') ?? '';
  const amount = Number(amountStr);
  if (!orderId || !Number.isFinite(amount)) {
    return { ok: false };
  }
  // 表面危险点：模板字符串直接拼接外部参数构造 SQL（CWE-89 形态）
  const sql = `SELECT status, paid_amount FROM payment_orders WHERE order_no = '${orderId}'`;
  const client: PoolClient = await roPool.connect();
  try {
    await client.query('BEGIN TRANSACTION READ ONLY');
    const found = await client.query(sql);
    if (found.rowCount === 0) {
      await client.query('ROLLBACK');
      return { ok: false };
    }
    const row = found.rows[0];
    await client.query('COMMIT');
    return { ok: row.status === 'PAID' && Number(row.paid_amount) === amount };
  } finally {
    client.release();
  }
}
