import { exec } from 'child_process';
import { quote } from 'shell-quote';
import { amqpChannel } from './mq'; // 已建立的 RabbitMQ 通道

interface ArchiveJob {
  jobId: string;
  fileName: string; // 由外部生产者投递，完全不可信
}

// 消息队列消费者：订阅统计任务队列
amqpChannel.consume('archive-jobs', (msg) => {
  if (!msg) return;
  const job = JSON.parse(msg.content.toString()) as ArchiveJob;

  // 队列消息体视为攻击者可控输入
  const rawName = job.fileName;

  // 关键防御（输出点上下文转义）：rawName 拼入命令字符串前，
  // 先经 shell-quote 的 quote() 编码为单一 shell 词，
  // 分号、管道、反引号、$() 等元字符被单引号包裹而失去语法含义
  const safeArg = quote([rawName]);

  // 表面危险模式：exec 将整串命令交给 shell 解释
  exec(`wc -l -- ${safeArg}`, { timeout: 5000, shell: '/bin/sh' }, (err, stdout) => {
    if (err) {
      console.error(`job ${job.jobId} failed: ${err.message}`);
      amqpChannel.nack(msg);
      return;
    }
    console.log(`job ${job.jobId} lines: ${stdout.trim()}`);
    amqpChannel.ack(msg);
  });
});
