// 会话管理组件：校验客户端上报的续期时长并刷新会话
interface SessionRecord {
  sid: string;
  ttlMinutes: number;
  refreshedAt: number;
}

const activeSessions = new Map<string, SessionRecord>();

// 表面危险：嵌套量词正则，若直接匹配攻击者可控长串可触发 CWE-1333 回溯爆炸
const TTL_PATTERN: RegExp = /^(\s*\d+\s*)+$/;

function parseTtlMinutes(raw: string): number {
  // 防御：强类型转换，仅当输入可解析为安全整数时才放行
  const ttl = Number.parseInt(raw, 10);
  if (!Number.isSafeInteger(ttl) || ttl <= 0 || ttl > 1440) {
    throw new RangeError('ttl must be integer minutes within 1..1440');
  }
  return ttl;
}

export function renewSession(sid: string, rawTtl: string): boolean {
  const ttl = parseTtlMinutes(rawTtl); // 外部字符串在此被强转为 number
  const canonical = String(ttl); // 进入正则的是规范化纯数字串
  if (!TTL_PATTERN.test(canonical)) { // 危险正则只接触强转结果
    return false;
  }
  activeSessions.set(sid, { sid, ttlMinutes: ttl, refreshedAt: Date.now() });
  return true;
}
