import * as fs from 'fs';
import * as path from 'path';

const TEMPLATE_ROOT = path.resolve(__dirname, 'templates');

function deserializeTemplateManifest(content: string): { subject: string; body: string } {
  const parsed = JSON.parse(content);
  return { subject: String(parsed.subject ?? ''), body: String(parsed.body ?? '') };
}

export function renderEmailTemplate(templateName: string): { subject: string; body: string } {
  const realRoot = fs.realpathSync(TEMPLATE_ROOT);
  const candidate = path.join(realRoot, `${templateName}.json`);

  let canonical: string;
  try {
    canonical = fs.realpathSync(candidate);
  } catch {
    throw new Error('template_not_found');
  }

  const rel = path.relative(realRoot, canonical);
  if (rel === '' || rel.startsWith('..') || path.isAbsolute(rel)) {
    throw new Error('template_outside_root');
  }
  if (!canonical.startsWith(realRoot + path.sep)) {
    throw new Error('template_prefix_mismatch');
  }

  const raw = fs.readFileSync(canonical, 'utf8');
  return deserializeTemplateManifest(raw);
}

