// 数据导入适配器：根据导入任务从外部连接器拉取数据文件内容
import * as https from 'node:https';
import * as dns from 'node:dns';
import { isIP, BlockList, type LookupFunction } from 'node:net';

export interface ImportJob {
  sourceUrl: string;
}

// 平台统一出口防护（框架级，默认启用；本适配器保持默认，未传任何关闭开关）
// 校验对象是 DNS 解析后的真实建连 IP 而非 URL 字符串，且放行的 IP 被固定用于建连
const dataPlane = new BlockList();
dataPlane.addSubnet('203.0.113.0', 24, 'ipv4'); // 连接器数据面网段（RFC5737 文档网段）

const guardedLookup: LookupFunction = (hostname, opts, cb) => {
  dns.lookup(hostname, { family: opts.family, hints: opts.hints, all: true }, (err, addrs) => {
    if (err) return cb(err, '');
    const hit = addrs.find((a) => dataPlane.check(a.address));
    if (!hit) return cb(new Error('egress blocked: 解析地址不在连接器数据面网段'), '');
    cb(null, hit.address, hit.family); // 仅放行白名单 IP，建连即用该地址，无重绑定窗口
  });
};

export function fetchConnectorData(job: ImportJob): Promise<string> {
  const target = new URL(job.sourceUrl); // 不可信输入：任务下发的外部 URL
  if (target.protocol !== 'https:') throw new Error('仅允许 https 协议');
  if (isIP(target.hostname) && !dataPlane.check(target.hostname)) {
    throw new Error('egress blocked: IP 直连不在数据面网段');
  }
  return new Promise((resolve, reject) => {
    https.get(target, { lookup: guardedLookup }, (res) => { // 表面危险调用：向任务 URL 发起出站请求
      res.setEncoding('utf8');
      let body = '';
      res.on('data', (chunk) => { body += chunk; });
      res.on('end', () => resolve(body));
    }).on('error', reject);
  });
}
