```typescript
import { Pool } from 'pg';
import { createHmac, timingSafeEqual } from 'crypto';

// 防御核心：回调查询走最小权限只读通道，数据库侧已执行：
//   GRANT SELECT ON orders_public_view TO payment_cb_ro;
// 该角色无任何其他授权，且非超级用户。
const roPool = new Pool({
  host: process.env.PG_HOST,
  database: process.env.PG_DB,
  user: 'payment_cb_ro',
  options: '-c default_transaction_read_only=on',
  max: 5
});

export async function handlePaymentCallback(raw: { orderId: string; amount: number; sign: string }) {
  if (!verifySign(raw.orderId, raw.amount, raw.sign)) throw new Error('bad signature');
  // 表面危险：orderId 未参数化，直接拼接进 SQL
  const sql = "SELECT order_no, amount, status FROM orders_public_view WHERE order_no = '" + raw.orderId + "'";
  const res = await roPool.query(sql);
  if (res.rowCount === 0) throw new Error('order not found');
  const order = res.rows[0];
  if (Number(order.amount) !== raw.amount) throw new Error('amount mismatch');
  await markPaid(order.order_no, raw.amount);
  return { ok: true, orderNo: order.order_no };
}

// 写通道独立：专用角色 + 参数化存储过程调用，无任何拼接
async function markPaid(orderNo: string, amount: number) {
  const rw = new Pool({ host: process.env.PG_HOST, database: process.env.PG_DB, user: 'payment_cb_writer' });
  try {
    await rw.query('CALL mark_order_paid($1, $2)', [orderNo, amount]);
  } finally {
    await rw.end();
  }
}

function verifySign(orderId: string, amount: number, sign: string): boolean {
  const expect = createHmac('sha256', process.env.CALLBACK_SECRET!).update(orderId + '|' + amount).digest('hex');
  return sign.length === expect.length && timingSafeEqual(Buffer.from(expect), Buffer.from(sign));
}
