import * as path from 'path';
import { promises as fs } from 'fs';

// 邮件模板服务：按用户提供的模板 ID 加载模板定义并反序列化
const TEMPLATE_BASE = path.resolve(__dirname, 'mail-templates');

interface MailTemplate {
  subject: string;
  body: string;
}

// 反序列化 reviver：阻断 __proto__ / constructor / prototype 原型污染键
function safeReviver(key: string, value: unknown): unknown {
  if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
    return undefined;
  }
  return value;
}

function deserializeTemplate(raw: string): MailTemplate {
  return JSON.parse(raw, safeReviver) as MailTemplate;
}

export async function loadMailTemplate(templateId: string): Promise<MailTemplate> {
  const candidate = path.join(TEMPLATE_BASE, templateId + '.json');
  const canonical = path.resolve(candidate);
  const rel = path.relative(TEMPLATE_BASE, canonical);
  // 双重校验一：relative 结果不得为空、不得上跳（..）、不得为绝对路径
  if (rel === '' || rel.startsWith('..') || path.isAbsolute(rel)) {
    throw new Error('模板路径越界，已拒绝');
  }
  // 双重校验二：规范化绝对路径必须仍位于模板根目录前缀之下
  if (!canonical.startsWith(TEMPLATE_BASE + path.sep)) {
    throw new Error('模板路径越界，已拒绝');
  }
  const raw = await fs.readFile(canonical, 'utf8');
  return deserializeTemplate(raw);
}
