public class WebhookOutboundSender
{
    private static readonly HttpClient http = new HttpClient();

    // 回调地址取自服务端部署配置，不接收 HTTP 请求输入
    private static readonly string callbackUrl =
        Environment.GetEnvironmentVariable("WEBHOOK_CALLBACK_URL") ?? "http://127.0.0.1:9000/hook";

    // webhook 出站发送器：读取查询参数，组装 HTML 投递回执，
    // 回写响应并出站推送到远端回调地址。
    public async System.Threading.Tasks.Task DispatchAsync(HttpContext ctx)
    {
        string rawEventId = ctx.Request.Query["eventId"];
        string rawRetries = ctx.Request.Query["retries"];

        // 防御：int 强类型转换，非数字或空输入在转换处抛出异常，
        // 引号、尖括号、onerror 等注入载荷无法存活到拼接点，
        // 转换成功后变量仅可能为 32 位整数。
        int eventId = int.Parse(rawEventId);
        int retries = Convert.ToInt32(rawRetries);

        string receipt = "<html><body><p>event=" + eventId +
                         " retries=" + retries + "</p></body></html>";

        await ctx.Response.WriteAsync(receipt);

        var payload = new StringContent(receipt, Encoding.UTF8, "text/html");
        await http.PostAsync(callbackUrl, payload);
    }
