using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;

namespace OpsKit
{
    public static class OpsCommandLoader
    {
        // 受信命令根目录：部署期由管理员创建，ACL 仅授予运维组写权限
        private static readonly string TrustedRoot = Path.GetFullPath(
            Path.Combine(AppContext.BaseDirectory, "trusted-commands"));

        public static object LoadCommandDefinition(string requestedPath)
        {
            // 第一重校验：规范化请求路径，消除 ..、相对段与冗余分隔符
            string candidate = Path.GetFullPath(requestedPath);
            if (!IsInsideTrustedRoot(candidate))
            {
                throw new UnauthorizedAccessException("命令定义必须位于受信目录内");
            }

            using (FileStream fs = File.OpenRead(candidate))
            {
                // 第二重校验：对已打开句柄的路径再次复核，双重确认落点仍在受信目录内
                if (!IsInsideTrustedRoot(fs.Name))
                {
                    throw new UnauthorizedAccessException("句柄路径复核失败");
                }

                BinaryFormatter formatter = new BinaryFormatter();
                return formatter.Deserialize(fs);
            }
        }

        // 规范化后按目录边界做前缀比对，杜绝兄弟目录前缀绕过
        private static bool IsInsideTrustedRoot(string path)
        {
            string full = Path.GetFullPath(path);
            string prefix = TrustedRoot.EndsWith(Path.DirectorySeparatorChar.ToString(),
                StringComparison.Ordinal) ? TrustedRoot
                : TrustedRoot + Path.DirectorySeparatorChar;
            return full.StartsWith(prefix, StringComparison.OrdinalIgnoreCase);
        }
    }
}
