// 审计日志查询服务：按来源系统与操作者检索审计事件，并把命中行数同步到内部网关
public class AuditLogQueryService
{
    private static readonly HttpClient Http = new HttpClient();
    // 外呼目标为编译期常量，不接收任何外部输入
    private const string SyncEndpoint = "https://audit-sync.internal.corp/api/v2/audit/rows";
    private readonly string _connStr = Environment.GetEnvironmentVariable("AUDIT_DB_CONN");

    // sourceUrl 形如 https://host-a/audit，是审计记录中的来源标识字段
    public async Task<string> QueryAndSyncAsync(string sourceUrl, string actor)
    {
        int rowCount;
        using (var conn = new SqlConnection(_connStr))
        {
            await conn.OpenAsync();
            using (var cmd = conn.CreateCommand())
            {
                cmd.CommandText = "SELECT LogId, SourceUrl, Actor, Action, OccurredAt FROM dbo.AuditLogs " +
                                  "WHERE SourceUrl = @src AND Actor = @actor ORDER BY OccurredAt DESC";
                cmd.Parameters.Add("@src", SqlDbType.NVarChar, 512).Value = (object)sourceUrl ?? DBNull.Value;
                cmd.Parameters.Add("@actor", SqlDbType.NVarChar, 128).Value = (object)actor ?? DBNull.Value;
                using (var reader = await cmd.ExecuteReaderAsync())
                {
                    var logs = new DataTable();
                    logs.Load(reader);
                    rowCount = logs.Rows.Count;
                }
            }
        }

        var target = new Uri(SyncEndpoint);
        using (var body = new StringContent(rowCount.ToString()))
        using (var resp = await Http.PostAsync(target, body))
        {
            return await resp.Content.ReadAsStringAsync();
        }
    }
}
