    public static void Main(string[] args)
    {
        string userInputName = args.Length > 0 ? args[0] : "app-2024.log";
        ArchiveLog(userInputName);
    }

    // 外部输入的日志名进入外部进程调用，表面上是 CWE-78 风险点
    public static void ArchiveLog(string userInputName)
    {
        string safeName = Path.GetFileName(userInputName);
        string logPath = Path.Combine("/var/log/app", safeName);

        if (!File.Exists(logPath))
        {
            Console.WriteLine("log file not found");
            return;
        }

        var psi = new ProcessStartInfo
        {
            FileName = "/usr/bin/tar",
            UseShellExecute = false,
            RedirectStandardOutput = true
        };

        psi.ArgumentList.Add("-czf");
        psi.ArgumentList.Add("archive.tar.gz");
        psi.ArgumentList.Add(logPath);

        using Process proc = Process.Start(psi);
        proc.WaitForExit(5000);
        Console.WriteLine("archive exit code: " + proc.ExitCode);
    }
}
