using System;
using System.Net.Http;
using System.Text;
using System.Web;

public class OutboundWebhookSender
{
    // 出站 webhook 发送器：把事件状态页片段推送给订阅方
    public static bool SendEventHook(HttpClient client, string subscriberEndpoint, string rawEventId, string rawAttempts)
    {
        try
        {
            // rawEventId 与 rawAttempts 源于查询串，若直接拼入 HTML 即构成 CWE-79 注入链
            int eventId = int.Parse(rawEventId);    // 强类型闸口：HTML 元字符在此抛 FormatException
            int attempts = int.Parse(rawAttempts);  // 第二个外部入口同样先收口再使用
            string banner = "<div class='evt'>event:" + eventId.ToString() + "</div>";
            string payload = "<html><body>" + banner +
                             "<span>attempts:" + attempts.ToString() + "</span></body></html>";
            using var content = new StringContent(payload, Encoding.UTF8, "text/html");
            using var resp = client.PostAsync(subscriberEndpoint, content).GetAwaiter().GetResult();
            return resp.IsSuccessStatusCode;
        }
        catch (FormatException)
        {
            return false; // 非数字输入直接拒绝，原始串不进入任何出站通道
        }
    }

    // 入口示例：参数取自请求查询串
    public static bool Handle(string queryString, HttpClient client, string endpoint)
    {
        var qs = HttpUtility.ParseQueryString(queryString);
        return SendEventHook(client, endpoint, qs["event_id"], qs["attempts"]);
    }
}
