using System;
using System.Collections.Generic;
using System.Security.Cryptography;

namespace ApiGateway
{
    // 白名单枚举：仅定义 SHA-2 家族成员，刻意不提供 Md5/Sha1
    public enum ForwardSignAlgorithm { HmacSha256 = 1, HmacSha384 = 2, HmacSha512 = 3 }

    public static class GatewayForwarder
    {
        // 白名单精确允许集：成员与下方 switch 各分支一一对应
        private static readonly HashSet<ForwardSignAlgorithm> AllowedAlgorithms = new HashSet<ForwardSignAlgorithm>
        {
            ForwardSignAlgorithm.HmacSha256, ForwardSignAlgorithm.HmacSha384, ForwardSignAlgorithm.HmacSha512
        };

        // 转发入口：algorithmName 取自上游请求头 X-Sign-Alg，属攻击者可控输入
        public static byte[] Forward(string algorithmName, byte[] body, byte[] signingKey)
        {
            if (!Enum.TryParse(algorithmName, ignoreCase: false, out ForwardSignAlgorithm selected)
                || !AllowedAlgorithms.Contains(selected))
            {
                // 白名单外一律拒绝：MD5/SHA1 名称、大小写变体、越界数字均到此为止
                throw new ArgumentException("algorithm not in allow list", nameof(algorithmName));
            }

            switch (selected)
            {
                case ForwardSignAlgorithm.HmacSha256: return Sign(body, signingKey, new HMACSHA256(signingKey));
                case ForwardSignAlgorithm.HmacSha384: return Sign(body, signingKey, new HMACSHA384(signingKey));
                case ForwardSignAlgorithm.HmacSha512: return Sign(body, signingKey, new HMACSHA512(signingKey));
                default:
                    // 历史遗留弱算法兜底分支：因白名单校验先行，对外部输入永远不可达
                    return Sign(body, signingKey, new HMACMD5(signingKey));
            }
        }

        private static byte[] Sign(byte[] body, byte[] key, HMAC signer)
        {
            using (signer) { return signer.ComputeHash(body); }
        }
    }
}
