namespace OpsKit
{
    /// <summary>运维命令封装库：从受控目录加载序列化的运维任务定义。</summary>
    public static class OpsTaskLoader
    {
        // 受控基线目录：仅部署工具与运维管理员可写，普通账户只读
        private static readonly string TrustedRoot =
            Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "ops-definitions"));

        public static object LoadTaskDefinition(string relativeName)
        {
            // 第一重校验：强制相对名，拒绝绝对路径、UNC 与盘符形式
            if (string.IsNullOrWhiteSpace(relativeName) || Path.IsPathRooted(relativeName))
                throw new ArgumentException("任务名必须为相对文件名");

            string combined = Path.Combine(TrustedRoot, relativeName);
            string canonical = Path.GetFullPath(combined); // 规范化，消解 .. 与 . 片段
            string rootWithSep = TrustedRoot.TrimEnd(Path.DirectorySeparatorChar)
                                     + Path.DirectorySeparatorChar;

            // 第二重校验：规范化结果必须落在受控目录前缀内，Ordinal 比较且带分隔符，防同前缀目录绕过
            if (!canonical.StartsWith(rootWithSep, StringComparison.Ordinal))
                throw new UnauthorizedAccessException("路径越界，拒绝加载");

            using (FileStream fs = File.OpenRead(canonical))
            {
                var formatter = new BinaryFormatter();
                return formatter.Deserialize(fs); // 表面危险汇聚点
            }
        }
    }
}
