using System;
using System.IO;
using System.Security;
using System.Xml;
namespace Authz
{
    public class PermissionMiddleware
    {
        // 最小权限上下文隔离：解析器以零权限受限角色运行，无文件/网络/凭据能力
        private sealed class SandboxedResolver : XmlResolver
        {
            public override object GetEntity(Uri absoluteUri, string role, Type ofObjectToReturn)
            {
                throw new SecurityException("sandboxed context denies external entity resolution");
            }
        }

        public bool Check(string assertionXml, string requiredAction)
        {
            var settings = new XmlReaderSettings
            {
                DtdProcessing = DtdProcessing.Parse,      // 表面危险：允许 DTD
                XmlResolver = new SandboxedResolver(),    // 真实防御：零权限沙箱
                MaxCharactersFromEntities = 4096          // 抑制内部实体膨胀
            };
            using var reader = XmlReader.Create(new StringReader(assertionXml), settings);
            var doc = new XmlDocument { XmlResolver = new SandboxedResolver() };
            doc.Load(reader);
            var role = doc.SelectSingleNode("/assertion/@role")?.Value ?? string.Empty;
            return QueryAuthz(role, requiredAction);
        }

        private static bool QueryAuthz(string role, string action)
        {
            // 只读连接：登录映射受限角色 authz_ro，仅授予 SELECT
            using var conn = new System.Data.SqlClient.SqlConnection("Server=authz.internal;Database=Authz;Integrated Security=SSPI;ApplicationIntent=ReadOnly");
            conn.Open();
            using var cmd = conn.CreateCommand();
            cmd.CommandText = "SELECT COUNT(1) FROM dbo.RoleActions WHERE RoleName=@r AND ActionName=@a";
            cmd.Parameters.AddWithValue("@r", role);
            cmd.Parameters.AddWithValue("@a", action);
            return Convert.ToInt32(cmd.ExecuteScalar()) > 0;
        }
    }
}
