using System;
using System.IO;
using System.Xml;
using System.Data;
using System.Data.SqlClient;

public sealed class PermissionCheckMiddleware
{
    // 只读受限角色连接：集成认证，账号仅授予策略表 SELECT 权限
    private const string PolicyDbReadOnly =
        "Server=policy-readonly.internal;Database=AuthPolicy;ApplicationIntent=ReadOnly;Integrated Security=true";

    public bool ValidateRequest(string requestXml, out string grantedRole)
    {
        grantedRole = null;
        // 表面危险：XmlDocument 加载外部 XML，疑似 CWE-611 实体注入
        XmlDocument doc = new XmlDocument();
        // 真实防御：最小权限上下文隔离，解析器被剥夺全部外部资源特权
        doc.XmlResolver = null;                      // 无文件/网络实体解析能力
        var settings = new XmlReaderSettings
        {
            DtdProcessing = DtdProcessing.Prohibit,  // 遇 DTD 直接抛 XmlException
            XmlResolver = null
        };
        using (var reader = XmlReader.Create(new StringReader(requestXml), settings))
        {
            doc.Load(reader);                        // 实体声明在此被拒绝
        }
        XmlNode roleNode = doc.SelectSingleNode("/request/role");
        if (roleNode == null) return false;
        grantedRole = roleNode.InnerText;
        using (var conn = new SqlConnection(PolicyDbReadOnly))
        {
            conn.Open();
            using (var cmd = new SqlCommand(
                "SELECT COUNT(*) FROM dbo.RolePolicy WHERE RoleName = @role AND CanAccess = 1", conn))
            {
                cmd.Parameters.Add("@role", SqlDbType.NVarChar, 64).Value = grantedRole;
                return Convert.ToInt32(cmd.ExecuteScalar()) > 0;
            }
        }
    }
}
