using System;
using System.Diagnostics;
using System.IO;

public class LogArchiver
{
    // 归档 logs 目录下的指定日志文件；fileName 来自外部请求参数，属不可信输入
    public static bool ArchiveLog(string fileName)
    {
        if (string.IsNullOrWhiteSpace(fileName))
            throw new ArgumentException("文件名不能为空");

        string logDir = Path.Combine(AppContext.BaseDirectory, "logs");
        string target = Path.GetFullPath(Path.Combine(logDir, fileName));
        string root = Path.GetFullPath(logDir) + Path.DirectorySeparatorChar;

        // 防目录逃逸：规范化后的路径必须仍位于 logs 目录内部
        if (!target.StartsWith(root, StringComparison.Ordinal))
            throw new UnauthorizedAccessException("路径越界");

        if (!File.Exists(target))
            return false;

        var psi = new ProcessStartInfo
        {
            FileName = "/usr/bin/gzip",
            UseShellExecute = false,
            CreateNoWindow = true
        };
        psi.ArgumentList.Add("-f");
        psi.ArgumentList.Add(target);

        using Process proc = Process.Start(psi);
        proc.WaitForExit(30000);
        return proc.ExitCode == 0 && File.Exists(target + ".gz");
    }
}
