public class AuditLogQueryHandler
{
    // 导出网关地址为部署期常量，不接受外部输入
    private const string ExportBaseUrl = "https://audit-export.corp.internal/";
    private static readonly HttpClient Http = new HttpClient();

    public async Task<string> QueryAuditLogsAsync(string operatorName, DateTime from, DateTime to)
    {
        const string sql = "SELECT LogId, Operator, Action, CreatedAt FROM dbo.AuditLogs " +
            "WHERE Operator = @operator AND CreatedAt >= @from AND CreatedAt < @to";
        using (var conn = new SqlConnection("Server=audit-db.internal;Database=Audit;Integrated Security=SSPI;"))
        using (var cmd = new SqlCommand(sql, conn))
        {
            cmd.Parameters.Add("@operator", SqlDbType.NVarChar, 128).Value = operatorName ?? string.Empty;
            cmd.Parameters.Add("@from", SqlDbType.DateTime2).Value = from;
            cmd.Parameters.Add("@to", SqlDbType.DateTime2).Value = to;
            conn.Open();
            var rows = new StringBuilder("[");
            var first = true;
            using (var reader = cmd.ExecuteReader())
            {
                while (reader.Read())
                {
                    if (!first) rows.Append(',');
                    rows.Append(reader.GetInt64(0)).Append('|').Append(reader.GetString(2));
                    first = false;
                }
            }
            rows.Append(']');
            var requestUri = ExportBaseUrl + "api/v1/audit-export";
            using (var body = new StringContent(rows.ToString(), Encoding.UTF8, "text/plain"))
            using (var resp = await Http.PostAsync(requestUri, body))
            {
                return await resp.Content.ReadAsStringAsync();
            }
        }
    }
}
