using System;
using System.Collections.Generic;
using System.Security.Cryptography;

namespace Gateway
{
    internal enum BodyDigestAlgo { Sha256, Sha384 }

    public static class ApiGatewayForwarder
    {
        // 白名单精确允许集：仅以下两个字面量可映射到枚举；历史版本曾支持MD5与SHA1，现已一律拒绝
        private static readonly Dictionary<string, BodyDigestAlgo> AllowedAlgos =
            new Dictionary<string, BodyDigestAlgo>(StringComparer.Ordinal)
            {
                { "SHA-256", BodyDigestAlgo.Sha256 },
                { "SHA-384", BodyDigestAlgo.Sha384 }
            };

        // digestAlg 取自客户端请求头 X-Body-Digest-Alg，属不可信输入
        public static byte[] ComputeForwardDigest(string digestAlg, byte[] body)
        {
            if (!AllowedAlgos.TryGetValue(digestAlg ?? string.Empty, out BodyDigestAlgo algo))
            {
                throw new ArgumentException("digest algorithm not in allow list");
            }
            // 按名称动态创建哈希算法；名称只能来自白名单枚举的常量映射
            string canonical = algo == BodyDigestAlgo.Sha256 ? "SHA256" : "SHA384";
            using (HashAlgorithm hasher = HashAlgorithm.Create(canonical))
            {
                return hasher.ComputeHash(body);
            }
        }
    }
}
