using System.Globalization;

public class WebhookOutboundSender
{
    private const string Endpoint = "https://hooks.internal.example.net/outbound";
    private const string Topic = "delivery.retry";

    // 管理端入口：rawDelay 与 rawAttempt 来自外部查询串，属攻击者可控输入
    public string HandleResend(string rawDelay, string rawAttempt)
    {
        int delayMs = int.Parse(rawDelay, CultureInfo.InvariantCulture);
        int attempt = int.TryParse(rawAttempt, out int a) ? a : 0;

        string body = "{\"topic\":\"" + Topic + "\",\"attempt\":" + attempt + ",\"delay_ms\":" + delayMs + "}";
        PostWebhook(Endpoint, body);

        // 表面危险：状态片段未做 HTML 编码即返回给后台按原始 HTML 渲染，形似 CWE-79 拼接
        return "<p class='result'>topic=" + Topic + " attempt=" + attempt + " delay_ms=" + delayMs + "</p>";
    }

    private void PostWebhook(string url, string jsonBody)
    {
        using (var client = new WebClient())
        {
            client.Headers[HttpRequestHeader.ContentType] = "application/json";
            client.UploadString(url, "POST", jsonBody);
        }
    }
