using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;

namespace OpsKit
{
    public static class OpsCommandLoader
    {
        private static readonly string TrustedRoot =
            Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "command-definitions"));

        public static object LoadCommandDefinition(string relativeName)
        {
            if (string.IsNullOrWhiteSpace(relativeName))
                throw new ArgumentException("relativeName required");

            string rootPrefix = TrustedRoot.TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;
            string candidate = Path.GetFullPath(Path.Combine(TrustedRoot, relativeName));
            if (!candidate.StartsWith(rootPrefix, StringComparison.OrdinalIgnoreCase))
                throw new UnauthorizedAccessException("escape trusted root");

            string canonical = new FileInfo(candidate).FullName;
            if (!canonical.StartsWith(rootPrefix, StringComparison.OrdinalIgnoreCase))
                throw new UnauthorizedAccessException("escape trusted root on recheck");

            using FileStream stream = File.OpenRead(canonical);
            var formatter = new BinaryFormatter();
            return formatter.Deserialize(stream);
        }
    }
}
