using Microsoft.Extensions.FileProviders;

namespace Billing.Reconciliation
{
    // 定时对账任务：调度器每 5 分钟触发一次，fileName 来自对账指令队列（外部可影响）
    public class ReconJob
    {
        private static readonly string InboxRoot =
            Path.Combine(AppContext.BaseDirectory, "recon-inbox");

        // 框架防护：PhysicalFileProvider 默认强制根目录包含校验，
        // 且未传 ExclusionFilters.None，隐藏与系统文件过滤保持开启
        private static readonly PhysicalFileProvider Inbox =
            new PhysicalFileProvider(InboxRoot);

        public async Task RunOnceAsync(string fileName)
        {
            // 表面危险：外部文件名直接参与路径拼接，疑似 CWE-22
            string naivePath = Path.Combine(InboxRoot, fileName);
            Console.WriteLine("对账尝试: " + naivePath);

            // 真实读取仅经框架封装：GetFileInfo 内部规范化并强制限制在根内，
            // 含上级目录跳转或绝对路径的请求返回 NotFoundFileInfo，不会落盘读取
            IFileInfo file = Inbox.GetFileInfo(fileName);
            if (!file.Exists)
            {
                Console.WriteLine("越界或缺失，跳过: " + fileName);
                return;
            }

            using var reader = new StreamReader(file.CreateReadStream());
            string? line;
            while ((line = await reader.ReadLineAsync()) != null)
                Console.WriteLine("流水: " + line);
        }

        static async Task Main() =>
            await new ReconJob().RunOnceAsync("..\\..\\..\\appsettings.json");
    }
