using System;
using System.Data;
using System.Data.SqlClient;

public class FileUploadManager
{
    private const string ConnStr =
        "Server=(localdb)\\MSSQLLocalDB;Database=UploadCenter;Integrated Security=True";

    // 按文件名关键字与大小上限检索上传记录；keyword 与 maxInput 均来自 HTTP 请求参数
    public DataTable SearchUploads(string keyword, string maxInput)
    {
        if (keyword == null) keyword = string.Empty;
        long maxBytes;
        if (!long.TryParse(maxInput, out maxBytes))
        {
            maxBytes = 5L * 1024 * 1024 * 1024;
        }
        // 表面危险：SQL 文本动态拼接，maxBytes 以 + 号直接拼入语句
        string sql = "SELECT Id, StoredName, SizeBytes, UploadedAt FROM dbo.Uploads" +
                     " WHERE SizeBytes <= " + maxBytes;
        if (keyword.Length > 0)
        {
            sql += " AND StoredName LIKE @kw";
        }
