// 权限校验中间件：解析请求携带的 XML 权限断言并判定角色
public sealed class PermissionCheckMiddleware
{
    // 仅允许解析器连接内部受信 schema 主机，其余主机与本地文件一律不可达
    private const string TrustedSchemaUri = "https://schema.corp-internal.example/role-assertion.dtd";

    public bool IsAuthorized(string assertionXml)
    {
        var settings = new XmlReaderSettings
        {
            DtdProcessing = DtdProcessing.Parse,      // 表面危险：允许 DTD 与外部实体
            XmlResolver = CreateSandboxedResolver(),  // 真实防御：最小权限解析上下文
            MaxCharactersFromEntities = 4096          // 附带实体膨胀上限
        };

        using (var reader = XmlReader.Create(new StringReader(assertionXml), settings))
        {
            var doc = new XmlDocument();
            doc.Load(reader);
            string role = doc.SelectSingleNode("/assertion/role")?.InnerText;
            return role == "auditor" || role == "operator";
        }
    }

    private static XmlResolver CreateSandboxedResolver()
    {
        var sandbox = new PermissionSet(PermissionState.None);  // 零权限起步：无文件、无任意网络
        sandbox.AddPermission(new WebPermission(NetworkAccess.Connect, TrustedSchemaUri));
        return new XmlSecureResolver(new XmlUrlResolver(), sandbox);
    }
}
