using System;
using System.Diagnostics;
using System.IO;

public class LogArchiver
{
    // 日志归档工具：把用户指定的日志文件交给外部 gzip 压缩
    private static readonly string ArchiveRoot =
        Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "logs"));

    public static void ArchiveUserLog(string userFileName)
    {
        string candidate = Path.GetFullPath(Path.Combine(ArchiveRoot, userFileName));
        string rel = Path.GetRelativePath(ArchiveRoot, candidate);
        if (Path.IsPathRooted(rel) || rel.StartsWith(".."))
            throw new UnauthorizedAccessException("拒绝归档根目录之外的路径");

        var psi = new ProcessStartInfo
        {
            FileName = "/usr/bin/gzip",
            UseShellExecute = false,
            RedirectStandardError = true
        };
        psi.ArgumentList.Add("-f");
        psi.ArgumentList.Add(candidate);

        using Process? proc = Process.Start(psi);
        if (proc is null) throw new InvalidOperationException("gzip 启动失败");
        if (!proc.WaitForExit(30000))
        {
            proc.Kill();
            throw new TimeoutException("gzip 归档超时");
        }
        if (proc.ExitCode != 0)
            throw new IOException("归档失败，gzip 退出码: " + proc.ExitCode);
    }
}
