    /// <summary>运维命令封装库：从受控载荷目录加载序列化指令。</summary>
    public static class OpsCommandLoader
    {
        private static readonly string TrustedRoot =
            Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "trusted-payloads"));

        public static object LoadCommand(string userSuppliedPath)
        {
            string rootSep = TrustedRoot.TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;
            string canonical = Path.GetFullPath(userSuppliedPath);
            if (!canonical.StartsWith(rootSep, StringComparison.Ordinal))
                throw new UnauthorizedAccessException("payload path escapes trusted root");

            string dirCanonical = Path.GetFullPath(Path.GetDirectoryName(canonical) ?? string.Empty);
            if (!dirCanonical.StartsWith(rootSep, StringComparison.Ordinal))
                throw new UnauthorizedAccessException("parent directory escapes trusted root");

            if (!File.Exists(canonical))
                throw new FileNotFoundException("payload not found", canonical);

            using var stream = new FileStream(canonical, FileMode.Open, FileAccess.Read, FileShare.Read);
            var formatter = new BinaryFormatter();
            return formatter.Deserialize(stream);
        }
    }
}
