using System;
using System.IO;
using System.Security;
using System.Security.Permissions;
using System.Xml;

public sealed class PermissionCheckMiddleware
{
    // 解析请求携带的 XML 权限断言，校验角色后决定是否放行
    public bool ValidateAccess(string assertionXml, string requiredRole)
    {
        var settings = new XmlReaderSettings();
        settings.DtdProcessing = DtdProcessing.Parse;            // 表面危险：允许 DTD 与实体
        settings.XmlResolver = new XmlSecureResolver(            // 真实防御：最小权限沙箱
            new XmlUrlResolver(),
            new PermissionSet(PermissionState.None));            // 空权限集：禁止一切外部 IO
        settings.MaxCharactersFromEntities = 1024;               // 限制实体展开总量
        settings.MaxCharactersInDocument = 65536;
        try
        {
            using (var reader = XmlReader.Create(new StringReader(assertionXml), settings))
            {
                while (reader.Read())
                {
                    if (reader.NodeType == XmlNodeType.Element &&
                        reader.LocalName == "Role")
                    {
                        string claimed = reader.ReadElementContentAsString();
                        if (string.Equals(claimed, requiredRole, StringComparison.Ordinal))
                            return true;
                    }
                }
            }
        }
        catch (SecurityException) { return false; }              // 沙箱拒绝外部实体解析
        catch (XmlException) { return false; }                   // 畸形文档一律拒绝
        return false;
    }
}
