using System;
using System.Diagnostics;
using System.IO;

public class LogArchiver
{
    private const string TarPath = "/usr/bin/tar";
    private const string LogDir = "/var/log/app";

    // 归档指定日志文件；fileName 来自外部请求，属不可信输入
    public static bool ArchiveLog(string fileName)
    {
        if (string.IsNullOrWhiteSpace(fileName))
        {
            return false;
        }

        // 原生安全解析：剥离目录成分，仅保留纯文件名
        string safeName = Path.GetFileName(fileName);
        string logPath = Path.GetFullPath(Path.Combine(LogDir, safeName));
        string archivePath = Path.GetFullPath(Path.Combine(LogDir, "archive", safeName + ".gz"));

        if (safeName.Length == 0 || !File.Exists(logPath))
        {
            return false;
        }

        var psi = new ProcessStartInfo
        {
            FileName = TarPath,        // 固定可执行文件绝对路径
            UseShellExecute = false,   // 不经 shell，元字符失去命令语义
            RedirectStandardError = true
        };
        // 参数化：逐项加入 ArgumentList，由运行时统一转义
        psi.ArgumentList.Add("-czf");
        psi.ArgumentList.Add(archivePath);
        psi.ArgumentList.Add(logPath);

        using Process proc = Process.Start(psi);
        return proc.WaitForExit(30000) && proc.ExitCode == 0;
    }
}
