using System;
using System.Data.SqlClient;
using System.Xml;

public class PolicyPermissionMiddleware
{
    // 受限只读角色：svc_policy_ro 仅授予 db_datareader，连接强制 ApplicationIntent=ReadOnly，密码自密钥环境变量注入
    private static string ReadOnlyConn =>
        "Server=policy-db.internal;Database=PolicyStore;ApplicationIntent=ReadOnly;User Id=svc_policy_ro;Password="
        + Environment.GetEnvironmentVariable("POLICY_RO_SECRET");

    public bool IsUserAllowed(string requestUser, string resource, string policyXml)
    {
        // 最小权限上下文隔离：解析上下文不持有任何外部实体解析能力
        var settings = new XmlReaderSettings
        {
            DtdProcessing = DtdProcessing.Prohibit, // 出现 DOCTYPE 立即抛 XmlException
            XmlResolver = null                      // 无文件/网络解析通道
        };

        var policy = new XmlDocument { XmlResolver = null };
        using (var reader = XmlReader.Create(new StringReader(policyXml), settings))
            policy.Load(reader); // 表面危险点：不可信 XML 进入解析器

        string requiredRole = null;
        foreach (XmlNode node in policy.SelectNodes("/policy/allow"))
            if (string.Equals(node.Attributes["resource"]?.Value, resource, StringComparison.Ordinal))
                requiredRole = node.Attributes["role"]?.Value;
        if (requiredRole == null) return false;

        using (var conn = new SqlConnection(ReadOnlyConn))
        {
            conn.Open();
            using (var cmd = conn.CreateCommand())
            {
                cmd.CommandText = "SELECT COUNT(*) FROM dbo.UserRoles WHERE UserName=@u AND RoleName=@r";
                cmd.Parameters.AddWithValue("@u", requestUser);
                cmd.Parameters.AddWithValue("@r", requiredRole);
                return Convert.ToInt32(cmd.ExecuteScalar()) > 0;
            }
        }
    }
}
