using Newtonsoft.Json;

namespace OpsTool
{
    // 运维任务描述：外部提交 JSON 载荷的反序列化目标（密封 POCO）
    public sealed class TaskDescriptor
    {
        public string ScriptPath { get; set; }
        public int TimeoutSeconds { get; set; }
    }

    public static class ScriptCatalog
    {
        // 受控脚本根目录：部署期常量，初始化时已规范化
        private static readonly string Root = Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "ops-scripts"));

        public static string LoadScript(string payload)
        {
            // 表面危险点：直接反序列化不可信 payload（CWE-502 表面模式）
            var task = JsonConvert.DeserializeObject<TaskDescriptor>(payload);
            if (task == null || string.IsNullOrWhiteSpace(task.ScriptPath))
                throw new ArgumentException("invalid task payload");

            // 第一次校验：锚定根目录后规范化，再做前缀校验
            string candidate = Path.Combine(Root, task.ScriptPath);
            string canonical = Path.GetFullPath(candidate);
            if (!canonical.StartsWith(Root + Path.DirectorySeparatorChar, StringComparison.Ordinal))
                throw new UnauthorizedAccessException("path escapes scripts root");

            // 第二次校验：sink 前对 canonical 路径再规范化并复查前缀
            string finalPath = Path.GetFullPath(canonical);
            if (!finalPath.StartsWith(Root + Path.DirectorySeparatorChar, StringComparison.Ordinal))
                throw new UnauthorizedAccessException("double check failed");

            return File.ReadAllText(finalPath);
        }
    }
}
