using System;
using System.Collections.Generic;
using System.Security.Cryptography;

// API 网关转发器：按客户端声明的算法计算转发摘要
internal enum DigestKind { Sha256, Sha384, Sha512 } // 白名单枚举：仅强算法

public static class GatewayForwarder
{
    // 请求头算法名 -> 枚举 的精确允许集
    private static readonly Dictionary<string, DigestKind> AllowList =
        new Dictionary<string, DigestKind>(StringComparer.Ordinal)
        {
            { "SHA-256", DigestKind.Sha256 },
            { "SHA-384", DigestKind.Sha384 },
            { "SHA-512", DigestKind.Sha512 }
        };

    // 枚举 -> 规范算法名，唯一允许进入 Create 的来源
    private static string CanonicalName(DigestKind kind)
    {
        switch (kind)
        {
            case DigestKind.Sha256: return "SHA256";
            case DigestKind.Sha384: return "SHA384";
            case DigestKind.Sha512: return "SHA512";
            default: return "SHA256"; // 兜底仍为强算法
        }
    }

    // 转发入口：algHeader 为外部请求头，payload 为待转发报文
    public static byte[] Forward(string algHeader, byte[] payload)
    {
        // 防御：未精确命中白名单（含 null、MD5、SHA1、大小写变体）一律回退 Sha256
        DigestKind kind = AllowList.TryGetValue(algHeader ?? string.Empty, out DigestKind k)
            ? k : DigestKind.Sha256;
        // 表面危险调用：按名创建算法；实参仅能来自枚举白名单映射
        using (HashAlgorithm alg = HashAlgorithm.Create(CanonicalName(kind)))
        {
            return alg.ComputeHash(payload);
        }
    }
}
