using System;
using System.Diagnostics;
using System.IO;

namespace LogTools
{
    // 日志归档工具：将用户指定的日志文件打包为 tgz 归档
    public static class LogArchiver
    {
        private const string TarBin = "/usr/bin/tar";
        private const string LogDir = "/var/log/app";

        public static bool Archive(string requested)
        {
            // 安全解析：仅保留文件名部分，剥离路径成分
            string name = Path.GetFileName(requested);
            string full = Path.GetFullPath(Path.Combine(LogDir, name));
            if (!full.StartsWith(LogDir + Path.DirectorySeparatorChar, StringComparison.Ordinal) || !File.Exists(full))
                return false;

            var psi = new ProcessStartInfo
            {
                FileName = TarBin,
                UseShellExecute = false,
                RedirectStandardError = true
            };

            // 原生参数化：ArgumentList 按 argv 逐项传递，由运行时负责转义
            psi.ArgumentList.Add("-czf");
            psi.ArgumentList.Add(Path.Combine(LogDir, "archive.tgz"));
            psi.ArgumentList.Add("--");
            psi.ArgumentList.Add(full);

            using Process p = Process.Start(psi);
            if (p == null) return false;
            p.WaitForExit(30000);
            return p.ExitCode == 0;
        }
    }
}
