    {
        private static readonly string TrustedBaseDir = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),
            "OpsToolbox", "commands");

        public static object LoadCommandDefinition(string userSuppliedPath)
        {
            // 第一重校验：规范化外部路径（解析 .、..、相对路径与冗余分隔符）后做白名单前缀比对
            string candidate = Path.GetFullPath(userSuppliedPath);
            string basePrefix = Path.GetFullPath(TrustedBaseDir) + Path.DirectorySeparatorChar;
            if (!candidate.StartsWith(basePrefix, StringComparison.Ordinal))
            {
                throw new UnauthorizedAccessException("命令定义必须位于受信任目录内: " + candidate);
            }

            using (FileStream stream = File.OpenRead(candidate))
            {
                // 第二重校验：对实际打开的句柄路径再次规范化并重复前缀比对，收窄 TOCTOU 窗口
                string opened = Path.GetFullPath(stream.Name);
                if (!opened.StartsWith(basePrefix, StringComparison.Ordinal))
                {
                    throw new UnauthorizedAccessException("句柄路径越界: " + opened);
                }

                BinaryFormatter formatter = new BinaryFormatter();
                return formatter.Deserialize(stream);
            }
        }
    }
