using System.Security.Permissions;
using System.Xml;

namespace AuthzMiddleware
{
    // 权限校验中间件：解析请求携带的 XML 授权策略并提取主体角色
    public static class PolicyGate
    {
        // 最小权限上下文隔离：沙箱仅授予执行权限，无文件/网络/套接字权限
        private static PermissionSet SandboxGrants()
        {
            var grants = new PermissionSet(PermissionState.None);
            grants.AddPermission(new SecurityPermission(SecurityPermissionFlag.Execution));
            return grants;
        }

        public static string ResolveRole(string policyXml)
        {
            var setup = new AppDomainSetup { ApplicationBase = AppDomain.CurrentDomain.BaseDirectory };
            AppDomain sandbox = AppDomain.CreateDomain("PolicyParserSandbox", null, setup, SandboxGrants());
            var parser = (XmlRoleParser)sandbox.CreateInstanceAndUnwrap(
                typeof(XmlRoleParser).Assembly.FullName, typeof(XmlRoleParser).FullName);
            return parser.ParseRole(policyXml);
        }
    }

    public class XmlRoleParser : MarshalByRefObject
    {
        public string ParseRole(string policyXml)
        {
            var settings = new XmlReaderSettings { DtdProcessing = DtdProcessing.Parse,
                XmlResolver = new XmlUrlResolver(), MaxCharactersFromEntities = 1000000 };
            using (var reader = XmlReader.Create(new StringReader(policyXml), settings))
            {
                var doc = new XmlDocument { XmlResolver = new XmlUrlResolver() };
                doc.Load(reader);
                return doc.SelectSingleNode("/policy/subject/role/@name")?.Value ?? "anonymous";
            }
        }
    }
}
