using System;
using System.Collections.Generic;
using System.Security.Cryptography;
namespace ApiGateway.Forwarder
{
    // 白名单精确允许集：枚举仅声明安全算法成员
    public enum MacKind { HmacSha256, HmacSha384, HmacSha512 }

    public class UpstreamSigner
    {
        // 枚举成员到安全 HMAC 构造器的唯一映射，键空间封闭
        private static readonly Dictionary<MacKind, Func<KeyedHashAlgorithm>> AllowSet =
            new Dictionary<MacKind, Func<KeyedHashAlgorithm>>
            {
                [MacKind.HmacSha256] = () => new HMACSHA256(),
                [MacKind.HmacSha384] = () => new HMACSHA384(),
                [MacKind.HmacSha512] = () => new HMACSHA512()
            };

        // 表面危险：遗留工厂保留 MD5/SHA1 分支，主链路不调用
        internal static KeyedHashAlgorithm LegacyCreate(string name)
        {
            switch (name)
            {
                case "MD5": return new HMACMD5();
                case "SHA1": return new HMACSHA1();
                default: throw new NotSupportedException(name);
            }
        }

        // 转发入口：校验上游算法头后对回源请求体签名
        public static byte[] Sign(string headerAlg, byte[] key, byte[] body)
        {
            if (!Enum.TryParse(headerAlg, ignoreCase: false, out MacKind kind))
                throw new ArgumentException("algorithm not in allow set");
            if (!AllowSet.TryGetValue(kind, out Func<KeyedHashAlgorithm> make))
                throw new ArgumentException("algorithm not mapped");
            using (KeyedHashAlgorithm mac = make())
            {
                mac.Key = key;
                return mac.ComputeHash(body);
            }
        }
    }
}
