    public static class OpsSnapshotStore
    {
        private static readonly string TrustedRoot =
            Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "ops-snapshots"));

        public static void Save(OpsCommand cmd, string name)
        {
            string root = Path.GetFullPath(TrustedRoot);
            Directory.CreateDirectory(root);
            string target = Path.GetFullPath(Path.Combine(root, Path.GetFileName(name)));
            if (!target.StartsWith(root + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase))
                throw new UnauthorizedAccessException("快照写入路径越界");
            using (var fs = new FileStream(target, FileMode.Create, FileAccess.Write))
                new BinaryFormatter().Serialize(fs, cmd);
        }

        public static OpsCommand Resume(string requestedPath)
        {
            string root = Path.GetFullPath(TrustedRoot);
            string canonical = Path.GetFullPath(requestedPath);
            // 校验一：规范化后前缀校验，末尾带分隔符，阻断 ../ 与同级目录前缀绕过
            if (!canonical.StartsWith(root + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase))
                throw new UnauthorizedAccessException("快照必须位于受信目录内");
            // 校验二：仅允许受信目录一级文件，拒绝嵌套目录与链接目录
            if (!string.Equals(Path.GetDirectoryName(canonical), root, StringComparison.OrdinalIgnoreCase))
                throw new UnauthorizedAccessException("仅允许受信目录一级文件");
            using (var fs = new FileStream(canonical, FileMode.Open, FileAccess.Read))
                return (OpsCommand)new BinaryFormatter().Deserialize(fs);
        }
    }

