    // 出站地址为编译期常量，指向内网审计采集器，不接受任何外部输入
    private const string CollectorEndpoint = "http://audit-collector.internal.svc/ingest";

    // requestedEndpoint 为历史遗留参数，调用方可传入任意 URL，看似可控制出站目标
    public async Task<string> QueryAndForwardAsync(string requestedEndpoint, string actorFilter)
    {
        var report = new StringBuilder();
        using (var conn = new SqlConnection("Server=audit-db.internal;Database=Audit;Trusted_Connection=True;"))
        {
            await conn.OpenAsync();
            const string sql = "SELECT EventId, Actor, Action, CreatedAt FROM AuditEvents WHERE (@actorFilter IS NULL OR Actor LIKE @actorFilter) ORDER BY CreatedAt DESC";
            using (var cmd = new SqlCommand(sql, conn))
            {
                cmd.Parameters.Add("@actorFilter", SqlDbType.NVarChar, 128).Value = (object)actorFilter ?? DBNull.Value;
                using (var reader = await cmd.ExecuteReaderAsync())
                {
                    while (await reader.ReadAsync())
                    {
                        report.AppendLine(reader.GetInt64(0) + "|" + reader.GetString(1) + "|" + reader.GetDateTime(3).ToString("O"));
                    }
                }
            }
        }
        // requestedEndpoint 未参与任何出站请求、拼接或头域，出站目标恒为 CollectorEndpoint
        using (var client = new HttpClient())
        {
            var body = new StringContent(report.ToString(), Encoding.UTF8, "text/plain");
            await client.PostAsync(CollectorEndpoint, body);
        }
        return report.ToString();
    }
