using System;
using System.Diagnostics;
using System.IO;

public static class LogArchiver
{
    // 场景：日志归档工具；logName 来自外部请求，可能携带 app.log & del /q D:\\Logs\\* 类载荷
    public static bool ArchiveLog(string logName)
    {
        // 防御一：Path.GetFileName 安全解析，剥离目录分隔符与穿越序列，仅保留纯文件名
        string safeName = Path.GetFileName(logName);
        string sourcePath = Path.Combine("D:\\AppLogs", safeName);
        if (!File.Exists(sourcePath))
        {
            return false;
        }

        string archivePath = Path.Combine("D:\\Archive", safeName + ".7z");

        var psi = new ProcessStartInfo
        {
            FileName = "C:\\Program Files\\7-Zip\\7z.exe",
            UseShellExecute = false,   // 防御二：不经 shell 解析，& | ; > 等元字符失去命令语义
            CreateNoWindow = true
        };

        // 防御三：ArgumentList 参数化传参，每个参数由运行时独立转义引用，外部输入无法拼接出新命令
        psi.ArgumentList.Add("a");
        psi.ArgumentList.Add(archivePath);
        psi.ArgumentList.Add(sourcePath);

        using Process proc = Process.Start(psi);
        proc.WaitForExit(60000);
        return proc.ExitCode == 0;
    }
}
