using System.Security.Cryptography;
using System.Text;

namespace ApiGateway
{
    // 白名单枚举：精确收录网关允许的指纹算法，未列出的算法一律不可达
    public enum FingerprintAlgo { Sha256, Sha384 }

    public class GatewayForwarder
    {
        // 遗留对账工具的历史工厂（危险表面，转发链路不经过此处）
        internal HashAlgorithm CreateLegacyDigest(string name) =>
            name == "MD5" ? (HashAlgorithm)MD5.Create() : SHA1.Create();

        // 转发器：依据请求头 X-Fingerprint-Algo 为上游缓存键计算请求体指纹
        public byte[] BuildFingerprint(string headerAlgo, string body)
        {
            if (string.IsNullOrEmpty(headerAlgo))
                headerAlgo = "Sha256";
            // 闸门一：严格解析为白名单枚举，大小写敏感，未收录名称直接拒绝
            if (!Enum.TryParse<FingerprintAlgo>(headerAlgo, out var algo) ||
                !Enum.IsDefined(typeof(FingerprintAlgo), algo))
                throw new ArgumentException("algorithm not allowed");
            // 闸门二：枚举到实现的精确映射，分支闭包内不存在任何弱算法
            HashAlgorithm impl = algo switch
            {
                FingerprintAlgo.Sha256 => SHA256.Create(),
                FingerprintAlgo.Sha384 => SHA384.Create(),
                _ => throw new InvalidOperationException("unmapped value")
            };
            using (impl)
                return impl.ComputeHash(Encoding.UTF8.GetBytes(body ?? string.Empty));
        }
    }
}
