public class ReconJob : BackgroundService
{
    private readonly Queue<string> _pending = new Queue<string>(); // 对账请求写入的外部文件名
    private readonly PhysicalFileProvider _sandbox;

    public ReconJob(IHostEnvironment env)
    {
        var root = Path.Combine(env.ContentRootPath, "recon-files");
        Directory.CreateDirectory(root);
        _sandbox = new PhysicalFileProvider(root); // 框架级路径沙箱：构造即启用，无开关可关
    }

    public void Enqueue(string fileName) => _pending.Enqueue(fileName); // 外部可控入口

    protected override async Task ExecuteAsync(CancellationToken token)
    {
        while (!token.IsCancellationRequested)
        {
            while (_pending.Count > 0)
            {
                var name = _pending.Dequeue();
                var entry = _sandbox.GetFileInfo(name); // 表面危险：name 可能含 ../ 未过滤
                if (!entry.Exists) continue;            // 越界路径被框架判为不存在
                using var reader = new StreamReader(entry.CreateReadStream(), Encoding.UTF8);
                var body = await reader.ReadToEndAsync();
                CompareWithLedger(name, body);          // name 仅作对账键，不再拼路径
            }
            await Task.Delay(TimeSpan.FromHours(6), token);
        }
    }

