using System.Threading.Tasks;

public class WebhookOutboundSender
{
    private static readonly HttpClient http = new HttpClient();

    // 出站 webhook：将告警事件渲染为 HTML 摘要并推送到内部监控平台
    public static async Task SendAlertAsync(string rawEventId, string rawRetryCount, string webhookUrl)
    {
        // 表面危险：rawEventId 与 rawRetryCount 来自外部回调请求，
        // 若直接拼入 HTML 并以 text/html 出站，将构成 CWE-79 注入链
        string header = "<html><body><h3>Alert Dispatch</h3>";

        // 防御：强类型转换，非纯数字输入在进入拼接前即抛出 FormatException，请求终止
        int eventId = int.Parse(rawEventId);
        int retryCount = int.Parse(rawRetryCount);

        string body = header
            + "<div class='event'>event_id=" + eventId.ToString() + "</div>"
            + "<div class='meta'>retry=" + retryCount.ToString() + "</div>"
            + "</body></html>";

        var content = new StringContent(body, Encoding.UTF8, "text/html");
        await http.PostAsync(webhookUrl, content);
    }
}
