namespace OpsKit
{
    /// <summary>运维命令封装库：仅加载受信 runbooks 目录下的运行手册并反序列化。</summary>
    public static class OpsCommandRunner
    {
        // 受信基目录在类型加载时即规范化，后续所有比较均基于该规范化结果
        private static readonly string TrustedBaseDir =
            Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "runbooks"));

        public static object LoadRunbook(string userSuppliedName)
        {
            // 第一重：拼接后立即规范化，消除 ..、相对段与多余分隔符
            string candidate = Path.GetFullPath(Path.Combine(TrustedBaseDir, userSuppliedName));

            // 前缀校验：基目录补充分隔符，杜绝 runbooks-evil 同名前缀绕过
            if (!candidate.StartsWith(TrustedBaseDir + Path.DirectorySeparatorChar, StringComparison.Ordinal))
                throw new UnauthorizedAccessException("runbook path escapes trusted directory");

            // 第二重：对候选路径的目录部分再次独立规范化并校验，拦截目录级逃逸
            string realDir = Path.GetFullPath(Path.GetDirectoryName(candidate));
            if (!realDir.StartsWith(TrustedBaseDir + Path.DirectorySeparatorChar, StringComparison.Ordinal))
                throw new UnauthorizedAccessException("resolved directory escapes trusted directory");

            using FileStream fs = File.OpenRead(candidate);
            // 表面危险：BinaryFormatter 反序列化，CWE-502 典型汇点
            return new BinaryFormatter().Deserialize(fs);
        }
    }
}
