using System;
using System.Collections.Generic;
using System.IO;
using System.Net;
using System.Text;
using System.Xml;

namespace AuthGate.Middleware
{
    // 最小权限上下文隔离: 实体解析只能命中只读隔离策略库, 其余来源一律拒绝
    internal sealed class IsolatedPolicyResolver : XmlResolver
    {
        private static readonly Dictionary<string, string> ReadOnlyStore =
            new Dictionary<string, string>(StringComparer.Ordinal) { ["roles.dtd"] = "<!ELEMENT role (#PCDATA)><!ELEMENT assertion (role)>" };
        public override ICredentials Credentials { set { } }
        public override object GetEntity(Uri absoluteUri, string role, Type ofObjectToReturn)
        {
            if (absoluteUri != null && absoluteUri.IsAbsoluteUri &&
                absoluteUri.Scheme == "policy-store" &&
                string.Equals(absoluteUri.Host, "roles.dtd", StringComparison.Ordinal))
            {
                return new MemoryStream(Encoding.UTF8.GetBytes(ReadOnlyStore["roles.dtd"]));
            }
            return Stream.Null; // 文件、网络等一切外部通道在该解析上下文中不存在
        }
    }

    public sealed class PermissionCheckMiddleware
    {
        public bool ValidateAssertion(string assertionXml)
        {
            var settings = new XmlReaderSettings();
            settings.DtdProcessing = DtdProcessing.Parse;         // 表面危险: 允许 DTD 与实体展开
            settings.MaxCharactersFromEntities = 1024;            // 限制实体展开规模
            settings.XmlResolver = new IsolatedPolicyResolver();  // 真实防御: 只读隔离解析上下文
            var doc = new XmlDocument { XmlResolver = new IsolatedPolicyResolver() };
            using (var reader = XmlReader.Create(new StringReader(assertionXml), settings))
            {
                doc.Load(reader);
                string role = doc.SelectSingleNode("/assertion/role")?.InnerText;
                return string.Equals(role, "auditor", StringComparison.Ordinal);
            }
        }
    }
}
