using System;
using System.Data;
using System.Data.SqlClient;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;

public class AuditLogQueryService
{
    // 内部日志采集器地址：编译期常量，非外部输入
    private const string CollectorEndpoint = "http://log-collector.internal.svc/audit/notify";
    private static readonly HttpClient Http = new HttpClient();

    // 按操作者与时间范围查询审计日志，并通知内部采集器
    public async Task<string> QueryAsync(string operatorName, DateTime from, DateTime to)
    {
        const string sql =
            "SELECT EventId, Action, TargetResource, CreatedAt FROM AuditLogs " +
            "WHERE Operator = @op AND CreatedAt BETWEEN @from AND @to ORDER BY CreatedAt DESC";
        var sb = new StringBuilder();
        using (var conn = new SqlConnection("Data Source=audit-db.internal;Initial Catalog=Audit;Integrated Security=True"))
        {
            await conn.OpenAsync();
            using (var cmd = new SqlCommand(sql, conn))
            {
                cmd.Parameters.Add("@op", SqlDbType.NVarChar, 128).Value = operatorName;
                cmd.Parameters.Add("@from", SqlDbType.DateTime2).Value = from;
                cmd.Parameters.Add("@to", SqlDbType.DateTime2).Value = to;
                using (var reader = await cmd.ExecuteReaderAsync())
                {
                    while (await reader.ReadAsync())
                        sb.AppendLine(reader["CreatedAt"] + "\t" + reader["Action"] + "\t" + reader["TargetResource"]);
                }
            }
        }
        // 表面疑似 SSRF 的外呼：目标为常量地址，不拼接任何用户输入
        using (var resp = await Http.PostAsync(CollectorEndpoint, new StringContent("audit query executed")))
        {
            resp.EnsureSuccessStatusCode();
        }
        return sb.ToString();
    }
}
