public static class LogArchiver
{
    private const string LogRoot = @"C:\AppLogs";
    private const string SevenZipPath = @"C:\Program Files\7-Zip\7z.exe";

    // userFile 来自外部请求参数，属于不可信输入
    public static void ArchiveLog(string userFile)
    {
        string candidate = Path.Combine(LogRoot, userFile);
        string fullPath = Path.GetFullPath(candidate);
        if (!fullPath.StartsWith(LogRoot + Path.DirectorySeparatorChar,
                                 StringComparison.OrdinalIgnoreCase))
        {
            throw new UnauthorizedAccessException("日志路径越界");
        }

        var psi = new ProcessStartInfo
        {
            FileName = SevenZipPath,
            UseShellExecute = false,
            RedirectStandardOutput = true
        };
        psi.ArgumentList.Add("a");
        psi.ArgumentList.Add(fullPath + ".7z");
        psi.ArgumentList.Add(fullPath);

        using Process proc = Process.Start(psi);
        string output = proc.StandardOutput.ReadToEnd();
        proc.WaitForExit();
        Console.WriteLine("归档退出码: " + proc.ExitCode);
    }
