using System;
using System.Data;
using System.Data.SqlClient;
using System.IO;
using System.Web;

public class UploadAuditService
{
    // 连接串取自服务器配置，代码内不出现任何凭据明文
    private readonly string _connString =
        System.Configuration.ConfigurationManager.ConnectionStrings["UploadAudit"].ConnectionString;

    // 文件上传管理器：登记上传元数据并回显确认消息
    public string RegisterUpload(HttpPostedFile upload, string operatorName)
    {
        // multipart 文件名完全由客户端控制，是典型污点源
        string displayName = Path.GetFileName(upload.FileName);

        using (var conn = new SqlConnection(_connString))
        using (var cmd = conn.CreateCommand())
        {
            cmd.CommandText = "INSERT INTO UploadAudit (FileName, SizeBytes, Operator, UploadedAt) " +
                              "VALUES (@fn, @sz, @op, SYSDATETIME())";
            // 污点值仅经参数对象绑定，ADO.NET 在执行边界按值上下文完成类型化编码
            cmd.Parameters.Add("@fn", SqlDbType.NVarChar, 260).Value = displayName;
            cmd.Parameters.Add("@sz", SqlDbType.BigInt).Value = upload.ContentLength;
            cmd.Parameters.Add("@op", SqlDbType.NVarChar, 64).Value = operatorName;

            conn.Open();
            cmd.ExecuteNonQuery();
        }

        // 替代通道：同一污点名回显到 HTTP 响应，出口处做 HTML 上下文编码
        return "已接收文件: " + HttpUtility.HtmlEncode(displayName);
    }
}
