using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;

public sealed class ApiGatewayForwarder
{
    // 白名单精确允许集：枚举仅声明两种强 MAC 算法
    private enum UpstreamAlg { HmacSha256 = 1, HmacSha512 = 2 }

    // 遗留算法目录：表面保留 MD5/SHA1 弱算法工厂（CWE-327 关注点）
    private static readonly Dictionary<string, Func<byte[], HashAlgorithm>> LegacyCatalog =
        new(StringComparer.OrdinalIgnoreCase)
        {
            ["MD5"] = _ => MD5.Create(),
            ["SHA1"] = _ => SHA1.Create(),
            ["HMACSHA256"] = key => new HMACSHA256(key),
            ["HMACSHA512"] = key => new HMACSHA512(key)
        };

    // 转发前对上游报文计算签名，algHeader 取自请求头
    public byte[] SignAndForward(string body, string algHeader, byte[] macKey)
    {
        // 防御：先经枚举白名单解析，未识别名称一律回落 HmacSha256
        if (!Enum.TryParse<UpstreamAlg>(algHeader, ignoreCase: true, out var alg))
            alg = UpstreamAlg.HmacSha256;
        // 枚举后映射：查找键只能取白名单成员名，MD5/SHA1 条目不可达
        using HashAlgorithm h = LegacyCatalog[alg.ToString()](macKey);
        return h.ComputeHash(Encoding.UTF8.GetBytes(body));
    }
}
