using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;

namespace OpsKit
{
    /// <summary>运维命令封装库：仅加载受信目录内的命令定义文件并反序列化执行。</summary>
    public static class OpsCommandLoader
    {
        // 受信命令根目录：命令定义由管理员投放，运维服务进程对其只读
        private static readonly string TrustedRoot =
            Path.GetFullPath(Path.Combine(AppContext.BaseDirectory, "trusted-commands"));

        public static OpsCommand Load(string userSuppliedPath)
        {
            // 第一重校验：规范化路径，折叠 .. 与相对段后再做前缀比对
            string canonical = Path.GetFullPath(userSuppliedPath
                ?? throw new ArgumentNullException(nameof(userSuppliedPath)));
            if (!canonical.StartsWith(TrustedRoot + Path.DirectorySeparatorChar, StringComparison.Ordinal))
                throw new UnauthorizedAccessException("拒绝加载受信目录之外的命令定义");

            // 第二重校验：解析符号链接最终目标后再次前缀比对，阻断链接逃逸
            FileInfo probe = new FileInfo(canonical);
            FileSystemInfo final = probe.ResolveLinkTarget(true) ?? probe;
            if (!final.FullName.StartsWith(TrustedRoot + Path.DirectorySeparatorChar, StringComparison.Ordinal))
                throw new UnauthorizedAccessException("链接目标越出受信目录");

            using FileStream fs = probe.OpenRead();
            var formatter = new BinaryFormatter();
            return (OpsCommand)formatter.Deserialize(fs);
        }
    }

    public class OpsCommand
    {
        public string Name;
        public string[] Args;
    }
}
