using System;
using System.IO;
using System.Linq;
using System.Security.Permissions;
using System.Xml;
namespace AuthMiddleware;
// 权限校验中间件：解析请求携带的 XML 授权策略，判定角色能否访问目标资源
public static class PermissionGate
{
    public static bool CheckAccess(string policyXml, string userRole, string resource)
    {
        // 最小权限上下文隔离：沙箱授权集仅含执行权限，无文件/网络/DNS 等 IO 权限
        var grants = new PermissionSet(PermissionState.None); grants.AddPermission(new SecurityPermission(SecurityPermissionFlag.Execution));
        var sandbox = AppDomain.CreateDomain("PolicyParseSandbox", null,
            new AppDomainSetup { ApplicationBase = AppDomain.CurrentDomain.BaseDirectory },
            grants, new PermissionSet(PermissionState.None));
        try
        {
            var parser = (PolicyParser)sandbox.CreateInstanceAndUnwrap(
                typeof(PolicyParser).Assembly.FullName, typeof(PolicyParser).FullName);
            return parser.ParseAndCheck(policyXml, userRole, resource);
        }
        catch { return false; } // 沙箱内解析失败（含外部实体被拒）一律拒绝访问
        finally { AppDomain.Unload(sandbox); }
    }
}
// 沙箱内运行的解析器：策略 XML 即使声明外部实体也无法读本地文件或外联
public class PolicyParser : MarshalByRefObject
{
    public bool ParseAndCheck(string policyXml, string userRole, string resource)
    {
        var settings = new XmlReaderSettings
        {
            DtdProcessing = DtdProcessing.Parse,   // 表面危险：允许 DTD 实体
            XmlResolver = new XmlUrlResolver(),    // 表面危险：允许解析外部实体
            MaxCharactersFromEntities = 4096,
            MaxCharactersInDocument = 65536
        };
        using var reader = XmlReader.Create(new StringReader(policyXml), settings);
        var doc = new XmlDocument();
        doc.Load(reader);
        return doc.SelectNodes("/policy/allow").Cast<XmlNode>().Any(n => n.Attributes["role"]?.Value == userRole
            && n.Attributes["resource"]?.Value == resource);
    }
}
