    // 出站 webhook 发送器：将告警事件推送到内部监控平台
    public class WebhookOutboundSender
    {
        private static readonly HttpClient client = new HttpClient();

        public void SendAlert(HttpRequest request)
        {
            // 外部不可信输入：告警级别与事件代码
            string rawLevel = request.QueryString["level"];
            string rawCode = request.Form["code"];

            // 两值随后会拼入下方 HTML 正文，必须先做强类型转换
            if (!int.TryParse(rawLevel, out int level) ||
