            // 该 HTML 会被监控端仪表盘渲染
            string htmlBody = "<html><body><p>Level: " + level +
                              " Code: " + code + "</p></body></html>";

            var content = new StringContent(htmlBody, Encoding.UTF8, "text/html");
            client.PostAsync("https://monitor.internal.local/hooks/alert", content).Wait();
        }
    }
