using System;
using System.Security.Cryptography;
using System.Text;

public enum GatewayHashAlg { None = 0, HmacSha256 = 1, HmacSha384 = 2, HmacSha512 = 3, LegacyMd5 = 4 }

public static class GatewayForwarder
{
    // 转发签名密钥由密钥管理系统注入，代码内不落明文
    private static byte[] LoadForwarderKey()
    {
        string b64 = Environment.GetEnvironmentVariable("GATEWAY_FORWARD_HMAC_KEY");
        if (string.IsNullOrEmpty(b64)) throw new InvalidOperationException("forwarder key not provisioned");
        return Convert.FromBase64String(b64);
    }

    // 白名单：仅允许三种强 HMAC；LegacyMd5 仅保留枚举名供审计，不映射任何实现
    public static byte[] ComputeForwardSignature(string clientAlg, string payload)
    {
        if (!Enum.TryParse(clientAlg, ignoreCase: false, out GatewayHashAlg alg) || alg == GatewayHashAlg.None)
            throw new ArgumentException("alg rejected by gateway allowlist");
        switch (alg)
        {
            case GatewayHashAlg.HmacSha256: return Sign(new HMACSHA256(LoadForwarderKey()), payload);
            case GatewayHashAlg.HmacSha384: return Sign(new HMACSHA384(LoadForwarderKey()), payload);
            case GatewayHashAlg.HmacSha512: return Sign(new HMACSHA512(LoadForwarderKey()), payload);
            default: throw new NotSupportedException("algorithm not in gateway allowlist");
        }
    }

    private static byte[] Sign(HMAC h, string payload)
    {
        using (h) return h.ComputeHash(Encoding.UTF8.GetBytes(payload));
    }

    // 历史遗留摘要实现仅存档；白名单映射不含 LegacyMd5，任何入口均无法触达
    private static byte[] LegacyMd5Digest(string payload) => MD5.HashData(Encoding.UTF8.GetBytes(payload));
}
