using System;
using System.Diagnostics;
using System.IO;

public class LogArchiver
{
    // 用法：dotnet run -- <日志文件名>，将 logs 目录下的指定日志打包归档
    public static int ArchiveLog(string userFileName)
    {
        string logDir = Path.Combine(AppContext.BaseDirectory, "logs");
        string target = Path.GetFullPath(Path.Combine(logDir, userFileName));

        // 目录边界校验：规范化后必须仍位于 logs 目录内，阻断路径逃逸
        if (!target.StartsWith(logDir + Path.DirectorySeparatorChar, StringComparison.Ordinal))
            throw new UnauthorizedAccessException("日志文件越界: " + userFileName);

        string archive = Path.Combine(AppContext.BaseDirectory, "archive",
            Path.GetFileNameWithoutExtension(target) + ".tar.gz");

        var psi = new ProcessStartInfo
        {
            FileName = "/usr/bin/tar",
            UseShellExecute = false,
            RedirectStandardError = true
        };
        // 关键防御：ArgumentList 逐参数传递，转义由运行时完成，
        // 文件名中的分号、竖线、反引号、$() 均作为字面字符交给 tar
        psi.ArgumentList.Add("-czf");
        psi.ArgumentList.Add(archive);
        psi.ArgumentList.Add("--");
        psi.ArgumentList.Add(target);

        using var proc = Process.Start(psi);
        proc.WaitForExit();
        return proc.ExitCode;
    }
}
