using System;
using System.Security;
using System.Security.Permissions;
using System.Threading;
using System.Xml;

namespace Auth
{
    // 权限校验中间件：解析请求方提交的 XML 授权策略，比对当前主体角色
    public sealed class PermissionCheckMiddleware
    {
        public bool CheckAccess(string policyXml, string requiredAction)
        {
            var doc = new XmlDocument();

            // 最小权限隔离：解析器以受限角色运行在零权限沙箱内，
            // 任何 file:// 或 http:// 外部实体解析都会因权限不足而失败
            var sandbox = new PermissionSet(PermissionState.None);
            doc.XmlResolver = new XmlSecureResolver(new XmlUrlResolver(), sandbox);

            doc.LoadXml(policyXml);

            foreach (XmlNode allow in doc.SelectNodes("/policy/allow"))
            {
                string action = allow.Attributes?["action"]?.Value;
                if (!string.Equals(action, requiredAction, StringComparison.Ordinal))
                    continue;
                string role = allow.Attributes?["role"]?.Value;
                if (role != null && Thread.CurrentPrincipal.IsInRole(role))
                    return true;
            }
            return false;
        }
    }
}
