import java.io.File

// 静态资源服务：按请求路径返回 webRoot 下的文件内容
object StaticFileServer {

    // 站点根目录，初始化时即规范化，作为唯一信任边界
    private val webRoot: File = File("/var/www/static").canonicalFile

    /** 返回文件字节内容；任何越界尝试一律返回 null */
    fun serve(requestPath: String): ByteArray? {
        if (requestPath.isBlank()) return null

        // 拼接候选路径
        val candidate = File(webRoot, requestPath)

        // 防御一：规范化，解析 .. 与 . 及符号链接，得到真实物理路径
        val canonical = candidate.canonicalFile

        // 防御二：双重前缀校验，目录边界必须精确
        val root = webRoot.canonicalPath
        val real = canonical.path
        val insideRoot = real == root || real.startsWith(root + File.separator)
        if (!insideRoot) return null

        // 仅放行普通文件，杜绝目录列举
        if (!canonical.isFile) return null

        return canonical.readBytes()
    }
}
