    fun loadDocument(cacheFile: File): RichTextDocument {
        ObjectInputStream(FileInputStream(cacheFile)).use { ois ->
            ois.setObjectInputFilter(DOC_FILTER)
            return ois.readObject() as RichTextDocument
        }
    }
