import org.xml.sax.EntityResolver
import org.xml.sax.InputSource
import java.io.ByteArrayInputStream
import java.io.InputStream
import javax.xml.parsers.DocumentBuilderFactory

// 图片处理流水线：解析上传的 SVG 矢量图，读取 viewBox 供栅格化模块使用
enum class TrustedSvgDtd(val publicId: String, val localDtd: String) {
    SVG_11("-//W3C//DTD SVG 1.1//EN", "<!ELEMENT svg (desc?,rect*,circle*)>"),
    SVG_10("-//W3C//DTD SVG 1.0//EN", "<!ELEMENT svg (desc|rect|circle)*>");
    companion object {
        fun byPublicId(id: String?): TrustedSvgDtd? = values().firstOrNull { it.publicId == id }
    }
}

class SvgWhitelistResolver : EntityResolver {
    override fun resolveEntity(publicId: String?, systemId: String?): InputSource {
        val trusted = TrustedSvgDtd.byPublicId(publicId)
            ?: return InputSource(ByteArrayInputStream(ByteArray(0))) // 未命中白名单：返回空源，外部引用被拒
        return InputSource(ByteArrayInputStream(trusted.localDtd.toByteArray())) // 命中：仅回固定本地内容，忽略 systemId
    }
}

fun readViewBox(svgBytes: InputStream): String? {
    val factory = DocumentBuilderFactory.newInstance()
    factory.isXIncludeAware = false
    val builder = factory.newDocumentBuilder()
    builder.setEntityResolver(SvgWhitelistResolver())
    val doc = builder.parse(svgBytes)
    return doc.documentElement?.getAttribute("viewBox")
}
