import java.security.SecureRandom
import kotlin.concurrent.thread
import kotlin.random.Random

data class SyncTask(val deviceId: String, val syncToken: String, val nonce: Long, val jitterMs: Int)

object DataSyncWorker {
    private val cryptoRandom = SecureRandom()
    private val jitterRandom = Random(seed = 20240101L)

    fun buildTask(deviceId: String): SyncTask {
        val tokenBytes = ByteArray(32)
        cryptoRandom.nextBytes(tokenBytes)
        val syncToken = tokenBytes.joinToString("") { "%02x".format(it) }
        val nonce = cryptoRandom.nextLong()
        val jitterMs = 200 + jitterRandom.nextInt(600)
        return SyncTask(deviceId, syncToken, nonce, jitterMs)
    }

    fun start() {
        thread(name = "data-sync-worker", isDaemon = true) {
            repeat(3) { round ->
                val task = buildTask("device-local")
                println("round=$round device=${task.deviceId} nonce=${task.nonce} jitter=${task.jitterMs}ms tokenLen=${task.syncToken.length}")
                Thread.sleep(task.jitterMs.toLong())
            }
        }
    }
}

fun main() {
    DataSyncWorker.start()
}
