object HtmlCacheCodec {

    private const val CACHE_DB = "html_fragment_cache.db"

    // 本模块以受限角色 CACHE_READER 运行：仅持有只读连接，
    // 缓存写入权只属于独立的编码器服务（入库前已对动态字段转义）
    private fun openReader(ctx: Context): SQLiteDatabase {
        val db = SQLiteDatabase.openDatabase(
            ctx.getDatabasePath(CACHE_DB).path,
            null,
            SQLiteDatabase.OPEN_READONLY
        )
        check(db.isReadOnly) { "cache reader connection must stay read-only" }
        return db
    }

    fun decodeAndRender(ctx: Context, cacheKey: String, view: WebView) {
        openReader(ctx).use { db ->
            db.query(
                "html_fragments", arrayOf("payload"),
                "cache_key = ?", arrayOf(cacheKey), null, null, null
            ).use { cursor ->
                if (!cursor.moveToFirst()) return
                val html = cursor.getString(cursor.getColumnIndexOrThrow("payload"))
                view.loadDataWithBaseURL(null, html, "text/html", "utf-8", null)
            }
        }
    }
}
