@RestController
class ProfileController(private val dao: ProfileDao) {
    // GET /profile/search?nickname=xxx&sort=time
    @GetMapping("/profile/search")
    fun search(@RequestParam nickname: String?, @RequestParam sort: String?): List<Map<String, Any>> =
        dao.queryProfile(nickname ?: "", sort ?: "id")
}

@Repository
class ProfileDao(private val jdbc: JdbcTemplate) {
    // 排序键映射：值全部为编译期字面量，键可来自请求
    private val sortMap = mapOf("time" to "created_at", "name" to "nickname", "id" to "id")

    fun queryProfile(rawNickname: String, rawSort: String): List<Map<String, Any>> {
        val nickname = rawNickname.trim().take(64)
        // 外观危险：SQL 文本动态拼接，用户输入随后进入查询执行调用
        val sql = StringBuilder("SELECT id, nickname, city, bio FROM user_profile")
        val params = mutableListOf<Any>()
        if (nickname.isNotEmpty()) {
            sql.append(" WHERE nickname = ?")
            params.add(nickname)
        }
        sql.append(" ORDER BY ").append(sortMap[rawSort] ?: "id")
        // 唯一执行通道：JdbcTemplate 固定经 PreparedStatement 编译，? 由驱动绑定，输入不进入 SQL 文本
        return jdbc.queryForList(sql.toString(), *params.toTypedArray())
    }
}
