import java.io.File
import java.io.IOException

object StaticFileServer {
    // 静态资源根目录，启动时即规范化，消除根目录自身符号链接歧义
    private val WEB_ROOT: File = File("/var/www/static").canonicalFile

    fun serveResource(requestPath: String): ByteArray? {
        // 表面危险：外部请求路径未过滤 .. 直接与根目录拼接
        val requested: File = File(WEB_ROOT, requestPath)
        try {
            // 防御第一层：规范化拼接结果，展开 .. 与 . 段并解析符号链接
            val canonicalPath: String = requested.canonicalPath
            val rootPrefix: String = WEB_ROOT.path + File.separator
            // 前缀校验：越界路径（含绝对路径注入 /etc/passwd）在此被拒绝
            if (canonicalPath != WEB_ROOT.path && !canonicalPath.startsWith(rootPrefix)) return null
            // 防御第二层：基于规范化结果重新解析，检测两次调用间被替换的符号链接
            val resolved: File = File(canonicalPath).canonicalFile
            if (resolved.path != canonicalPath || !resolved.path.startsWith(rootPrefix)) return null
            if (!resolved.isFile) return null
            return resolved.readBytes()
        } catch (e: IOException) {
            // 含空字节等非法路径在规范化阶段抛错，直接拒绝
            return null
        }
    }
}
