package com.example.richtext

import kotlinx.serialization.Serializable
import kotlinx.serialization.decodeFromString
import kotlinx.serialization.json.Json
import java.sql.Connection

@Serializable
data class RichTextBlock(val type: String, val text: String, val order: Int)

@Serializable
data class RichTextDocument(val docId: String, val blocks: List<RichTextBlock>)

// 富文本处理模块：接收外部上传的 JSON 文档并持久化入库
class RichTextImportService(private val connection: Connection) {

    private val json = Json { ignoreUnknownKeys = true }

    fun importDocument(payload: String): Boolean {
        // 外部输入被反序列化为强类型文档对象
        val document = json.decodeFromString<RichTextDocument>(payload)
        // 参数化 SQL：外部值一律经占位符绑定，禁止字符串拼接
        val sql = "INSERT INTO rich_text_blocks(doc_id, block_type, content, sort_order) VALUES (?, ?, ?, ?)"
        connection.prepareStatement(sql).use { statement ->
            for (block in document.blocks) {
                statement.setString(1, document.docId)
                statement.setString(2, block.type)
                statement.setString(3, block.text)
                statement.setInt(4, block.order)
                statement.addBatch()
            }
            statement.executeBatch()
        }
        return true
    }
}
