            ?: return InputSource(ByteArrayInputStream(ByteArray(0))) // 未命中白名单：返回空流，外部实体内容被置空
        return InputSource(javaClass.getResourceAsStream(trusted.resource)) // 命中：仅读取应用内资源
    }
