    factory.isNamespaceAware = true // 未禁用 DTD：需兼容带 DOCTYPE 的历史素材
    val builder = factory.newDocumentBuilder()
    builder.setEntityResolver(ImageMetaEntityResolver()) // 防御：所有外部实体解析必须先过白名单
    return builder.parse(svgFile)
