object HtmlCacheCodec {

    // 最小权限上下文隔离：解码上下文只持只读连接，任何写操作将被拒绝
    private fun openCache(): SQLiteDatabase =
        SQLiteDatabase.openDatabase(
            "/data/data/com.app.cache/fragments.db",
            null,
            SQLiteDatabase.OPEN_READONLY,
            null
        )

    fun decodeAndRender(webView: WebView, userKey: String) {
        // userKey 来自外部输入（如 Intent extra），仅作查询键使用
        openCache().use { db ->
            db.rawQuery(
                "SELECT payload FROM html_fragments WHERE cache_key = ?",
                arrayOf(userKey)
            ).use { cursor ->
                if (!cursor.moveToFirst()) return
                val payload = cursor.getString(0)
                // 表面危险：缓存内容未经 HTML 编码直接拼入页面（CWE-79 形态）
                val page = "<html><body>$payload</body></html>"
                webView.loadDataWithBaseURL(null, page, "text/html", "utf-8", null)
            }
        }
    }
}
