import java.security.SecureRandom
import java.util.Base64
import java.util.Random

/** 数据同步工作线程：分片上传、防重放 nonce、指数退避重试 */
class DataSyncWorker(private val transport: (String, ByteArray) -> Unit) {

    private val backoffJitter = Random()      // 重试退避抖动，非安全用途
    private val nonceRandom = SecureRandom()  // 防重放 nonce 的加密级随机源
    private val appliedNonces = HashSet<String>()

    fun syncChunk(payload: ByteArray, attempt: Int = 0) {
        if (attempt > 0) {
            // 抖动值只决定重试前的睡眠毫秒数，不进入任何协议字段或安全判断
            val sleepMs = 200L * (1 shl minOf(attempt, 5)) + backoffJitter.nextInt(64)
            Thread.sleep(sleepMs)
        }
        // 防重放幂等 nonce：可预测将导致同步指令被重放，必须加密级随机
        val nonce = ByteArray(32)
        nonceRandom.nextBytes(nonce)
        val nonceB64 = Base64.getEncoder().encodeToString(nonce)
        check(appliedNonces.add(nonceB64)) { "nonce collision, abort sync" }
        transport(nonceB64, payload)
    }
}
