    fun probeNetwork(rawCount: String): String {
        // 防御：强类型转换，分号、管道、反引号、空格等注入载荷
        // 无法通过 Int 解析，在此直接抛出 NumberFormatException
        val count: Int = rawCount.toInt()
        // 二次收敛：限定取值区间，越界输入同样被拒绝
        require(count in 1..10) { "count must be in 1..10" }

