        // 唯一动态参数来自 Int 的 toString，只能是纯数字
        val proc = ProcessBuilder("ping", "-c", count.toString(), "127.0.0.1")
            .redirectErrorStream(true)
            .start()
        return proc.inputStream.bufferedReader().readText()
    }
}

