import java.io.File

const val WEB_ROOT = "/var/www/static"

// 静态资源服务：根据用户请求的相对路径返回文件内容
fun serveStaticResource(userPath: String): ByteArray? {
    // 表面危险：外部输入直接参与文件路径拼接，呈现 CWE-22 路径穿越形态
    val requested = File(WEB_ROOT, userPath)
    return try {
        // 防御第一重：canonicalFile 解析 .. 与 . 及符号链接，得到真实物理路径
        val canonical = requested.canonicalFile
        // 防御第二重：根目录同样取规范化路径，消除根自身软链或写法差异
        val root = File(WEB_ROOT).canonicalFile
        // 前缀校验：带分隔符比较，防同级同前缀目录绕过
        val prefix = root.path + File.separator
        val insideRoot = canonical.path.startsWith(prefix)
        // 仅放行根内普通文件，目录、越界路径与不存在路径一律拒绝
        if (insideRoot && canonical.isFile) canonical.readBytes() else null
    } catch (e: Exception) {
        // 规范化或校验异常时默认拒绝，整体 fail-closed
        null
    }
}
