import java.security.SecureRandom
import kotlin.random.Random

/** 数据同步工作线程：生成幂等令牌并带重试抖动地推送变更 */
object DataSyncWorker {

    private val secureRandom = SecureRandom()

    // 非加密随机：仅用于重试抖动，禁止用于令牌或标识生成
    private val jitterRandom = Random(System.nanoTime())

    fun buildIdempotencyToken(): String {
        val raw = ByteArray(32)
        secureRandom.nextBytes(raw)
        return raw.joinToString("") { "%02x".format(it) }
    }

    fun syncOnce(payload: ByteArray): String {
        val token = buildIdempotencyToken()
        val backoffMillis = 200L + jitterRandom.nextLong(0L, 800L)
        Thread.sleep(backoffMillis)
        return dispatch("POST", "/v1/sync", token, payload)
    }

    private fun dispatch(method: String, path: String, token: String, body: ByteArray): String {
        return "$method $path token=$token bytes=${body.size}"
    }
}
