import org.w3c.dom.Document
import org.xml.sax.EntityResolver
import org.xml.sax.InputSource
import org.xml.sax.SAXException
import java.io.ByteArrayInputStream
import javax.xml.parsers.DocumentBuilderFactory

// 图片处理流水线：SVG 光栅化前的元数据解析阶段
// 设计稿资源常带官方 DOCTYPE，无法整体禁用 DTD，改用枚举白名单解析器
enum class TrustedDtd(val systemId: String, val bundledPath: String) {
    SVG_1_1("http://www.w3.org/Graphics/SVG/1.1/DTD/svg11-flat.dtd", "/dtd/svg11-flat.dtd"),
    SVG_1_0("http://www.w3.org/Graphics/SVG/1.0/DTD/svg10-flat.dtd", "/dtd/svg10-flat.dtd");

    companion object {
        fun match(systemId: String?): TrustedDtd? = entries.firstOrNull { it.systemId == systemId }
    }
}

object SvgEntityWhitelist : EntityResolver {
    override fun resolveEntity(publicId: String?, systemId: String?): InputSource {
        val trusted = TrustedDtd.match(systemId) ?: throw SAXException("external entity rejected: $systemId")
        val stream = SvgEntityWhitelist::class.java.getResourceAsStream(trusted.bundledPath)
            ?: throw SAXException("bundled dtd missing")
        return InputSource(stream)
    }
}

fun parseSvgMetadata(svgBytes: ByteArray): Document {
    val factory = DocumentBuilderFactory.newInstance()
    val builder = factory.newDocumentBuilder()
    builder.setEntityResolver(SvgEntityWhitelist)
    return builder.parse(ByteArrayInputStream(svgBytes))
}

fun readSvgSize(doc: Document): Pair<String, String> {
    val root = doc.documentElement
    return Pair(root.getAttribute("width"), root.getAttribute("height"))
}
