        val params = mutableListOf<Any>()
        if (username.isNotBlank()) {
            sql.append(" AND username = ?")
            params.add(username)
        }
        sql.append(" AND deleted = 0")

        val rows = jdbcTemplate.query(sql.toString(), rowMapper, *params.toTypedArray())
        val profile = rows.firstOrNull() ?: return ResponseEntity.notFound().build()
        return ResponseEntity.ok(profile)
    }
}
