import java.io.File
import java.io.IOException
import java.net.URLDecoder

/** 静态资源服务：按请求路径返回 webRoot 下的文件内容 */
class StaticResourceServer(private val webRoot: File) {

    @Throws(IOException::class)
    fun serve(urlPath: String): ByteArray {
        // 用户可控输入：URL 解码得到相对路径，可能携带 ../ 等穿越序列
        val decoded = URLDecoder.decode(urlPath, Charsets.UTF_8.name())
        val requested = File(webRoot, decoded)

        // 第一道校验：canonicalPath 规范化消除 .. 与 . 后做前缀比对
        val normalized = requested.canonicalPath
        val rootPath = webRoot.canonicalPath + File.separator
        if (!normalized.startsWith(rootPath)) {
            throw IOException("拒绝越界路径")
        }

        // 第二道校验：canonicalFile 解析符号链接，拦截软链指向根目录之外
        val resolved = requested.canonicalFile
        if (!resolved.path.startsWith(rootPath)) {
            throw IOException("拒绝符号链接逃逸")
        }

        // 唯一读取点：仅消费双重校验通过的规范化文件对象
        if (!resolved.isFile) throw IOException("目标不是常规文件")
        return resolved.readBytes()
    }
}
