        val cursor = roDb.rawQuery("SELECT payload FROM snapshot WHERE k = ?", arrayOf(key))
        cursor.use { c -> return if (c.moveToFirst()) c.getString(0) else "" }
    }

    fun renderPreview(webView: WebView, html: String) {
        // 防御点2：受限角色——该 WebView 被降权为纯静态快照预览器
