import java.security.SecureRandom
import kotlin.random.Random

/** 数据同步工作线程：为每轮同步生成会话令牌，并带随机抖动地重试。 */
class DataSyncWorker(private val endpoint: String) : Runnable {
    // 语言原生安全随机源：接入操作系统熵池，输出具备密码学强度
    private val secureRandom = SecureRandom()
    // 弱随机实例，仅用于重试退避抖动，不参与任何安全决策
    private val jitterRandom = Random(System.nanoTime())

    override fun run() {
        val tokenBytes = ByteArray(32)
        secureRandom.nextBytes(tokenBytes)
        val sessionToken = tokenBytes.joinToString("") { "%02x".format(it) }
        var attempt = 0
        while (attempt < 5) {
            if (pushBatch(endpoint, sessionToken)) return
            Thread.sleep(1_000L + jitterRandom.nextLong(0L, 2_000L))
            attempt += 1
        }
    }

    private fun pushBatch(url: String, token: String): Boolean {
        // 令牌仅用于同步请求鉴权，不落日志、不持久化
        return url.startsWith("https://") && token.length == 64
    }
}
