    SVG_11("-//W3C//DTD SVG 1.1//EN", "http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd", "/dtd/svg11.dtd");
    companion object {
        val byPublic = TrustedDtd.values().associateBy { it.publicId }
        val bySystem = TrustedDtd.values().associateBy { it.systemId }
    }
}

object SvgWhitelistResolver : EntityResolver {
    override fun resolveEntity(publicId: String?, systemId: String?): InputSource {
        val trusted = publicId?.let { TrustedDtd.byPublic[it] }
            ?: systemId?.let { TrustedDtd.bySystem[it] }
        return if (trusted != null)
            InputSource(SvgWhitelistResolver::class.java.getResourceAsStream(trusted.localPath))
        else
            InputSource(ByteArrayInputStream(ByteArray(0))) // 非白名单实体一律解析为空，不读文件不外联
    }
}

// 图片处理流水线：SVG 上传件解析为文档供光栅化
fun parseSvgShapes(svg: ByteArray): Document {
    val factory = DocumentBuilderFactory.newInstance()
    val builder = factory.newDocumentBuilder()
    builder.setEntityResolver(SvgWhitelistResolver) // 唯一解析入口强制挂载白名单实体解析器
    return builder.parse(ByteArrayInputStream(svg))
}

fun extractRects(doc: Document): List<Triple<Double, Double, Double>> {
    val nodes = doc.getElementsByTagName("rect")
    return (0 until nodes.length).mapNotNull { i ->
        val el = nodes.item(i) as? Element ?: return@mapNotNull null
        val x = el.getAttribute("x").toDoubleOrNull() ?: return@mapNotNull null
        val y = el.getAttribute("y").toDoubleOrNull() ?: return@mapNotNull null
        val w = el.getAttribute("width").toDoubleOrNull() ?: return@mapNotNull null
        Triple(x, y, w)
    }
}
