import java.io.File

object StaticFileServer {
    // 启动时对根目录做一次规范化, 固定可信基准
    private val webRoot: File = File("/var/www/static").canonicalFile
    private val rootPrefix: String = webRoot.path + File.separator

    // 处理 GET /static/<userPath> 的静态资源请求
    fun serveStatic(userPath: String): ByteArray? {
        // userPath 完全由请求方控制, 可能携带 ../../etc/passwd 等穿越载荷
        val requested = File(webRoot, userPath)
        // 第一重校验: canonicalFile 递归解析 . .. 与符号链接, 得到真实物理路径
        val canonical = requested.canonicalFile
        // 第二重校验: 规范化后的最终落点必须仍位于 webRoot 前缀之下
        if (!canonical.path.startsWith(rootPrefix)) {
            return null
        }
        // 仅允许普通文件, 拒绝目录与不存在路径
        if (!canonical.isFile) {
            return null
        }
        // 唯一读取汇点: 使用已通过双重校验的 canonical 对象
        return canonical.readBytes()
    }
}
