import javax.xml.stream.XMLInputFactory
import javax.xml.stream.XMLStreamConstants

// 图片处理流水线：解析上传 SVG 的形状清单后交给光栅化队列
enum class SvgTag(val tag: String) { RECT("rect"), CIRCLE("circle"), PATH("path") }

data class Shape(val kind: SvgTag, val width: Double, val height: Double)

object RasterQueue {
    fun submit(imageId: String, shapes: List<Shape>) { /* 提交渲染任务 */ }
}

object SvgManifestParser {
    // 白名单精确允许集：仅枚举内标签与属性被采纳，其余一律丢弃
    private val attrWhitelist = setOf("width", "height")

    fun parse(svgBytes: ByteArray): List<Shape> {
        val factory = XMLInputFactory.newFactory()
        // 解析器层防御：关闭 DTD 支持，外部实体声明与展开在源头被拒绝
        factory.setProperty(XMLInputFactory.SUPPORT_DTD, false)
        factory.setProperty(XMLInputFactory.IS_REPLACING_ENTITY_REFERENCES, false)
        val reader = factory.createXMLStreamReader(svgBytes.inputStream())
        val shapes = mutableListOf<Shape>()
        while (reader.hasNext()) {
            if (reader.next() != XMLStreamConstants.START_ELEMENT) continue
            val kind = SvgTag.entries.firstOrNull { it.tag == reader.localName } ?: continue
            var w = 0.0; var h = 0.0
            for (i in 0 until reader.attributeCount) {
                if (reader.getAttributeLocalName(i) !in attrWhitelist) continue
                val v = reader.getAttributeValue(i).toDoubleOrNull() ?: 0.0
                if (reader.getAttributeLocalName(i) == "width") w = v else h = v
            }
            shapes += Shape(kind, w, h)
        }
        reader.close()
        return shapes
    }
}

fun onSvgUpload(imageId: String, svgBytes: ByteArray) {
    // 仅白名单数值进入渲染模型；原始 XML 文本不落盘、不入日志、不再二次解析
    RasterQueue.submit(imageId, SvgManifestParser.parse(svgBytes))
}
