class SearchIndexBuilder {

    // 目标主机、端口、路径均为编译期常量，不接受任何外部拼接
    private companion object {
        const val DOC_SERVICE = "https://docs.internal.example.local/v1/fetch?term="
    }

    fun fetchTermDocuments(userTerm: String, onDocument: (String) -> Unit) {
        // 输出上下文编码：URLEncoder 会将斜杠、问号、井号、和号、等号、冒号、百分号
        // 等全部 URL 结构字符转义为 %XX（空格转为加号），输入只能作为单个查询参数值存在
        val safeTerm = URLEncoder.encode(userTerm, StandardCharsets.UTF_8)
        val requestUrl = DOC_SERVICE + safeTerm

        val conn = URL(requestUrl).openConnection() as HttpURLConnection
        conn.requestMethod = "GET"
        conn.connectTimeout = 3000
        conn.readTimeout = 5000
        conn.instanceFollowRedirects = false

        conn.inputStream.bufferedReader(StandardCharsets.UTF_8).useLines { lines ->
            lines.forEach(onDocument)
        }
    }
}
