import java.util.Properties

enum class BuildStatus { OK, FAILED, TIMEOUT }
enum class Role { ANON_RO, INGEST_RW }

// 缓存编解码模块：解码缓存中的预渲染片段并输出为 HTML
object SnippetCacheCodec {
    // 只读连接：open_mode=1 即 SQLITE_OPEN_READONLY，驱动层强制拒绝任何写操作
    private val ro: Connection = DriverManager.getConnection(
        "jdbc:sqlite:/var/cache/snippet.db",
        Properties().apply { put("open_mode", "1") }
    )

    // 入口：key 来自 HTTP 查询参数，属不可信输入
    fun decodeToHtml(key: String): String {
        ro.prepareStatement("SELECT body FROM snippet WHERE k = ?").use { ps ->
            ps.setString(1, key)
            val rs = ps.executeQuery()
            if (!rs.next()) return "<p>cache-miss</p>"
            val body = rs.getString("body")
            return "<section class=\"cached\">$body</section>"
        }
    }
}

// 唯一写入方：摄取 worker，须持受限角色 INGEST_RW，内容仅由服务端模板生成
object SnippetPublisher {
    fun publish(rw: Connection, role: Role, id: Long, status: BuildStatus) {
        check(role == Role.INGEST_RW) { "restricted writer role required" }
        val body = "<span data-build=\"$id\">build=${status.name}</span>"
        rw.prepareStatement("INSERT OR REPLACE INTO snippet(k, body) VALUES (?, ?)").use { ps ->
            ps.setLong(1, id)
            ps.setString(2, body)
            ps.executeUpdate()
        }
    }
}
