package com.editor.richtext.importer

import java.io.ObjectInputStream
import java.io.ObjectInputFilter
import java.io.Serializable
import java.sql.Connection

/** 富文本处理模块：导入序列化文档并落库 */
object RichTextImporter {

    // 白名单过滤器：仅放行业务文档类与 java.base 基础类，其余一律拒绝
    private val docFilter: ObjectInputFilter =
        ObjectInputFilter.Config.createFilter(
            "com.editor.richtext.importer.RichTextDocument;java.base/*;!*"
        )

    fun importDocument(payload: ByteArray, conn: Connection): Boolean {
        val doc = deserialize(payload) ?: return false
        if (doc.title.isBlank() || doc.body.length > 1_000_000) return false
        persist(doc, conn)
        return true
    }

    private fun deserialize(payload: ByteArray): RichTextDocument? = try {
        ObjectInputStream(payload.inputStream()).use { ois ->
            ois.setObjectInputFilter(docFilter)
            ois.readObject() as RichTextDocument
        }
    } catch (e: Exception) {
        null
    }

    private fun persist(doc: RichTextDocument, conn: Connection) {
        val sql = "INSERT INTO rich_text_docs(title, body) VALUES (?, ?)"
        conn.prepareStatement(sql).use { ps ->
            ps.setString(1, doc.title)
            ps.setString(2, doc.body)
            ps.executeUpdate()
        }
    }
}

data class RichTextDocument(val title: String, val body: String) : Serializable
