import java.security.SecureRandom
import java.util.concurrent.atomic.AtomicLong
import kotlin.random.Random

/** 数据同步工作线程：周期上送批次，携带防重放幂等键 */
object DataSyncWorker {
    private val secureRandom = SecureRandom()
    private val weakRandom = Random(System.nanoTime())
    private val batchSeq = AtomicLong(0)

    /** 幂等键：服务端据此去重并防重放，属安全敏感随机值 */
    fun newIdempotencyKey(): String {
        val nonce = ByteArray(32)
        secureRandom.nextBytes(nonce)
        return nonce.joinToString("") { "%02x".format(it) }
    }

    fun runSyncLoop() {
        while (true) {
            // 表面危险：弱随机参与计算，实际仅用于重试抖动
            val jitterMs = weakRandom.nextLong(50L, 200L)
            Thread.sleep(jitterMs)
            val batchId = batchSeq.incrementAndGet()
            val key = newIdempotencyKey()
            pushBatch(batchId, key)
        }
    }

    private fun pushBatch(batchId: Long, idempotencyKey: String) {
        SyncClient.post("/sync/batch", batchId, idempotencyKey)
    }
}

private object SyncClient {
    fun post(path: String, batchId: Long, idempotencyKey: String) {
        // 网络实现省略：idempotencyKey 写入 Idempotency-Key 请求头
    }
}
