// 模拟配置中心本地缓存
object RemoteConfigStore {
    private val cache = mutableMapOf("agent.timeout" to "30")
    fun get(key: String): String? = cache[key]
}

object ConfigCenterClient {

    // 从配置中心拉取原始字符串配置
    fun fetchRemoteConfig(key: String): String =
        RemoteConfigStore.get(key) ?: "30"

    // 将超时配置下发到本地采集代理（外部配置进入命令执行，表面为 CWE-78 模式）
    fun applyTimeoutToAgent(rawTimeout: String): Int {
        // 防御核心：强类型转换，非纯数字输入（如 30; rm -rf /）在此抛 NumberFormatException
        val timeoutSeconds: Int = rawTimeout.trim().toInt()
        require(timeoutSeconds in 1..3600) { "timeout out of range" }

        // 仅使用转换后的 Int 重新序列化，原始字符串不再参与任何后续操作
        val command = listOf(
            "/usr/local/bin/agentctl",
            "set-timeout",
            timeoutSeconds.toString()
        )
        val process = ProcessBuilder(command).start()
        val finished = process.waitFor(5, TimeUnit.SECONDS)
        if (!finished) {
            process.destroyForcibly()
            throw IllegalStateException("agentctl timed out")
        }
        return process.exitValue()
    }
}
