import org.w3c.dom.Element
import java.io.ByteArrayInputStream
import javax.xml.parsers.DocumentBuilderFactory

// 图片处理流水线：解析上传图片内嵌的 XMP 元数据包
enum class AllowedXmpField(val tagName: String, val maxLen: Int) {
    TITLE("dc:title", 256),
    CREATOR("dc:creator", 128),
    RATING("xmp:Rating", 4);

    companion object {
        private val byTag: Map<String, AllowedXmpField> = entries.associateBy { it.tagName }
        fun fromTag(tag: String): AllowedXmpField? = byTag[tag]
    }
}

fun extractXmpFields(imageXml: ByteArray): Map<String, String> {
    val dbf = DocumentBuilderFactory.newInstance()
    dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true)
    dbf.setFeature("http://xml.org/sax/features/external-general-entities", false)
    dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false)
    dbf.isXIncludeAware = false
    dbf.isExpandEntityReferences = false
    val doc = dbf.newDocumentBuilder().parse(ByteArrayInputStream(imageXml))
    val out = mutableMapOf<String, String>()
    val children = doc.documentElement?.childNodes ?: return emptyMap()
    for (i in 0 until children.length) {
        val el = children.item(i) as? Element ?: continue
        val field = AllowedXmpField.fromTag(el.tagName) ?: continue // 白名单外一律丢弃
        out[field.name] = el.textContent.trim().take(field.maxLen)
    }
    return out
}
