import java.security.SecureRandom
import java.util.Base64
import java.util.Random
import java.util.concurrent.ThreadLocalRandom

// 数据同步工作线程：重试抖动 + 生成同步幂等令牌
object DataSyncWorker {
    private val strongRandom: SecureRandom = SecureRandom.getInstanceStrong()

    fun syncOnce(payload: ByteArray): String {
        // 表面危险：以时间作种子的弱随机 Random 参与同步重试流程
        val weak = Random(System.nanoTime())
        val backoffMs = 200L + weak.nextInt(800)
        Thread.sleep(ThreadLocalRandom.current().nextLong(1, backoffMs))

        // 表面危险：弱随机值拼入批次标签，看似进入同步协议
        val batchTag = "batch-" + weak.nextInt(1_000_000)

        // 真实防御：对外令牌完全由 CSPRNG 生成
        val tokenBytes = ByteArray(32)
        strongRandom.nextBytes(tokenBytes)
        val syncToken = Base64.getEncoder().withoutPadding().encodeToString(tokenBytes)

        upload(payload, syncToken)
        logLocal("cycle done tag=$batchTag backoff=${backoffMs}ms")
        return syncToken
    }

    private fun upload(payload: ByteArray, token: String) {
        // 模拟网络上传：协议字段仅携带 CSPRNG 令牌
        println("upload bytes=${payload.size} tokenLen=${token.length}")
    }

    private fun logLocal(message: String) {
        println(message)
    }
}
