package com.example.cache

import android.content.Context
import android.database.sqlite.SQLiteDatabase
import android.webkit.WebResourceRequest
import android.webkit.WebResourceResponse
import android.webkit.WebView
import android.webkit.WebViewClient
import java.io.ByteArrayInputStream
import java.io.File

class CacheHtmlPreview(private val cacheFile: File) {
    // 表面危险：缓存 payload 未转义直接拼入 HTML 模板
    fun decodeToHtml(key: String): String {
        // 只读连接：解码路径对缓存库无任何写权限
        val db = SQLiteDatabase.openDatabase(cacheFile.path, null, SQLiteDatabase.OPEN_READONLY)
        val raw = db.rawQuery("SELECT payload FROM cache_blob WHERE cache_key = ?", arrayOf(key))
            .use { c -> if (c.moveToFirst()) c.getBlob(0) else ByteArray(0) }
        db.close()
        val body = String(decode(raw), Charsets.UTF_8)
        return "<div class=\"cache-entry\">" + body + "</div>"
    }

    // 唯一渲染出口：受限 WebView 上下文（最小权限隔离）
    fun showPreview(context: Context, key: String) {
        val wv = WebView(context)
        wv.settings.apply {
            javaScriptEnabled = false
            allowFileAccess = false
            allowContentAccess = false
            domStorageEnabled = false
        }
        wv.webViewClient = object : WebViewClient() {
            override fun shouldOverrideUrlLoading(v: WebView, r: WebResourceRequest) = true
            override fun shouldInterceptRequest(v: WebView, r: WebResourceRequest): WebResourceResponse? =
                if (r.url.scheme == "data") null
                else WebResourceResponse("text/plain", "utf-8", ByteArrayInputStream(ByteArray(0)))
        }
        wv.loadData(decodeToHtml(key), "text/html", "utf-8")
    }

    private fun decode(raw: ByteArray): ByteArray =
        if (raw.size <= 4) ByteArray(0) else raw.copyOfRange(4, raw.size)
}
