// 搜索索引构建器：把外部提交的文档登记进内部索引服务
class SearchIndexBuilder {

    // 固定的内部索引服务地址，scheme、host、port、path 全部为常量
    private val indexerEndpoint = "http://indexer.internal:8080/ingest"

    // source：外部用户提交的待索引文档地址与标题
    fun submitForIndexing(docUrl: String, title: String): Int {
        // 危险外观：用户输入参与拼接出站请求 URL，呈 CWE-918 形态
        // 防御：在输出点按查询参数上下文做百分号编码
        val query = "doc=" + URLEncoder.encode(docUrl, StandardCharsets.UTF_8) +
                "&title=" + URLEncoder.encode(title, StandardCharsets.UTF_8)
        val target = indexerEndpoint + "?" + query
        // sink：出站 HTTP 请求
        val conn = URI.create(target).toURL().openConnection() as HttpURLConnection
        conn.requestMethod = "GET"
        conn.connectTimeout = 3000
        conn.readTimeout = 5000
        val status = conn.responseCode
        // 响应体仅用于排空连接，不进入任何解释性输出通道
        conn.inputStream?.use { it.readBytes() }
        conn.disconnect()
        return status
    }
}
