import java.util.concurrent.TimeUnit

/**
 * 配置中心客户端：拉取拨测超时配置并触发本地健康检查命令。
 * 表面形态：外部配置字符串被拼入 Runtime.exec 命令行，呈现 CWE-78 特征。
 */
class ConfigCenterClient(private val snapshot: Map<String, String>) {

    // 来源：配置中心下发的原始字符串，配置被篡改时可携带任意文本
    fun fetchRawTimeout(): String = snapshot["probe.timeout"] ?: "5"

    // 防御点：强类型转换，非纯整数输入（如 5;reboot）在 toInt() 处
    // 抛出 NumberFormatException，数据流在此中断，无法抵达下方 exec
    fun parseTimeoutSeconds(): Int = fetchRawTimeout().trim().toInt()

    // 汇聚点：命令拼接看似危险，但参数静态类型为 Int，
    // 字符串插值只可能产生规范十进制整数字面量
    fun runHealthProbe(timeoutSeconds: Int): String {
        val cmd = "curl --max-time $timeoutSeconds -s http://127.0.0.1:8080/health"
        val proc = Runtime.getRuntime().exec(cmd)
        proc.waitFor(10, TimeUnit.SECONDS)
        return proc.inputStream.bufferedReader().readText()
    }

    // 唯一执行入口：先强转后使用，原始字符串无任何旁路进入命令
    fun executeProbe(): String = runHealthProbe(parseTimeoutSeconds())
}
