import java.io.File

const val STATIC_ROOT = "/var/www/app/static"

// 静态资源服务：根据请求路径返回文件内容
fun serveStatic(requestPath: String): StaticResult {
    // 入口预检：拒绝空请求与空字节注入
    if (requestPath.isEmpty() || requestPath.contains('\u0000')) {
        return StaticResult.error(400)
    }
    val cleaned = requestPath.trimStart('/')
    val baseDir = File(STATIC_ROOT).canonicalFile
    // 第一次规范化：拼接后取 canonical 路径，消解 .. 段并解析符号链接
    val candidate = File(baseDir, cleaned).canonicalFile
    // 第二次校验：规范化结果必须仍位于基目录前缀之内
    if (!candidate.path.startsWith(baseDir.path + File.separator)) {
        return StaticResult.error(403)
    }
    if (!candidate.isFile) {
        return StaticResult.error(404)
    }
    val bytes = candidate.readBytes()
    return StaticResult.ok(bytes)
}

data class StaticResult(val status: Int, val body: ByteArray?) {
    companion object {
        fun error(code: Int) = StaticResult(code, null)
        fun ok(body: ByteArray) = StaticResult(200, body)
    }
}
