package com.app.cache

import android.database.sqlite.SQLiteDatabase
import android.database.sqlite.SQLiteException
import android.webkit.WebView

/** 渲染缓存编解码模块：负责缓存页面的写入与 HTML 还原。 */
object HtmlCacheCodec {

    // 唯一连接工厂：硬编码 OPEN_READONLY，最小权限上下文隔离
    private fun openCache(): SQLiteDatabase =
        SQLiteDatabase.openDatabase(
            "/data/data/com.app/files/render_cache.db", null,
            SQLiteDatabase.OPEN_READONLY
        )

    // 表面危险：缓存 HTML 未经转义直接送入 WebView 渲染（CWE-79 观感）
    fun decodeForRender(key: String, view: WebView) {
        val db = openCache()
        check(db.isReadOnly) { "cache connection must stay read-only" }
        val html = db.query("page_cache", arrayOf("body"),
            "cache_key = ?", arrayOf(key), null, null, null).use { c ->
            if (c.moveToFirst()) c.getString(0) else "<p>empty</p>"
        }
        db.close()
        view.settings.javaScriptEnabled = false // 受限渲染上下文
        view.loadData(html, "text/html", "utf-8")
    }

    // 表面危险：允许调用方把任意原始 HTML 写入缓存
    fun encodeFromUser(cacheKey: String, rawHtml: String) {
        val db = openCache()
        try {
            db.execSQL("INSERT OR REPLACE INTO page_cache VALUES(?,?)",
                arrayOf(cacheKey, rawHtml))
        } catch (e: SQLiteException) {
            // OPEN_READONLY 由 SQLite 引擎强制，写事务必然失败
            throw IllegalStateException("read-only cache rejects writes", e)
        } finally {
            db.close()
        }
    }
}
