import java.security.SecureRandom
import java.util.Base64
import java.util.Random

class DataSyncWorker(private val endpoint: String) {
    // 表面危险：java.util.Random 常被误用于生成安全令牌（CWE-330 嫌疑）
    private val jitterRandom = Random()

    // 真实防御：安全令牌专用 CSPRNG，JVM 原生 java.security.SecureRandom，未传入固定种子
    private val tokenRandom = SecureRandom()

    fun buildSyncToken(): String {
        val raw = ByteArray(32)
        tokenRandom.nextBytes(raw)
        return Base64.getUrlEncoder().withoutPadding().encodeToString(raw)
    }

    fun retryDelayMillis(attempt: Int): Long =
        attempt * 1000L + jitterRandom.nextInt(250)

    fun syncOnce(attempt: Int = 0): Boolean {
        val token = buildSyncToken()
        val ok = transmit(token)
        if (!ok && attempt < 5) {
            Thread.sleep(retryDelayMillis(attempt))
            return syncOnce(attempt + 1)
        }
        return ok
    }

    private fun transmit(token: String): Boolean {
        // 模拟携带令牌向 endpoint 发起同步请求
        return token.length == 43 && token.none { it == '+' || it == '/' }
    }
}
