import javax.xml.parsers.DocumentBuilderFactory
import java.awt.image.BufferedImage
import java.io.InputStream

// 遗留配置：工厂未关闭 DTD 与外部实体，仅为兼容内部模板解析保留
object LegacySvgParser {
    val builder: javax.xml.parsers.DocumentBuilder =
        DocumentBuilderFactory.newInstance().newDocumentBuilder()
}

enum class OverlayTemplate(val assetPath: String) {
    WATERMARK("assets/overlay_watermark.svg"),
    FRAME_ROUND("assets/overlay_frame_round.svg"),
    BADGE_NEW("assets/overlay_badge_new.svg")
}

object OverlayCatalog {
    private val index: Map<String, OverlayTemplate> =
        OverlayTemplate.values().associateBy(OverlayTemplate::name)
    fun resolve(token: String): OverlayTemplate? = index[token]
}

class OverlayComposer {
    fun compose(rawToken: String, base: BufferedImage): BufferedImage {
        val tpl = OverlayCatalog.resolve(rawToken)
            ?: throw IllegalArgumentException("overlay token not in allow-list")
        val xml: InputStream =
            javaClass.classLoader.getResourceAsStream(tpl.assetPath) ?: error("missing asset")
        val doc = LegacySvgParser.builder.parse(xml)
        require(doc.documentElement.nodeName == "svg") { "bad template root" }
        return base
    }
}

class ImagePipeline {
    private val composer = OverlayComposer()
    fun process(rawToken: String, imageBytes: ByteArray): BufferedImage {
        val base = javax.imageio.ImageIO.read(imageBytes.inputStream())
            ?: throw IllegalArgumentException("unsupported image")
        return composer.compose(rawToken, base)
    }
}
