import java.io.File
import java.nio.file.Paths

const val WEB_ROOT = "/var/www/static"

// 静态资源服务：按用户请求的相对路径返回文件内容
fun serveStaticResource(userPath: String): ByteArray? {
    // 表面危险：用户输入直接参与路径拼接（疑似目录穿越入口）
    val requested = Paths.get(WEB_ROOT, userPath)

    // 防御一：normalize 消解路径中的 .. 与 . 段
    val normalized = requested.normalize().toAbsolutePath()

    // 防御二：canonical path 双重校验，解析符号链接后做前缀比对
    val canonical = normalized.toFile().canonicalPath
    val rootCanonical = File(WEB_ROOT).canonicalPath + File.separator
    if (!canonical.startsWith(rootCanonical)) {
        return null // 越出根目录的请求一律拒绝
    }

    val target = File(canonical)
    if (!target.isFile) return null
    return target.readBytes()
}

fun main() {
    // 攻击样例：穿越序列被规范化后落在根目录之外，返回 null
    println(serveStaticResource("../../etc/passwd") == null)
    // 正常样例：docs/readme.md 仍在根目录内，可正常读取
    println(serveStaticResource("docs/readme.md") != null)
}
