import org.xml.sax.EntityResolver
import org.xml.sax.InputSource
import javax.xml.XMLConstants
import javax.xml.parsers.DocumentBuilderFactory
import java.io.CharArrayReader

// 图片处理流水线：SVG 光栅化前的元数据读取步骤
// 白名单精确允许集：仅两个 W3C 官方 DTD 的 publicId 被映射到内置本地副本
enum class SvgDtdWhitelist(val publicId: String, val localResource: String) {
    SVG_11("-//W3C//DTD SVG 1.1//EN", "/dtd/svg11.dtd"),
    SVG_10("-//W3C//DTD SVG 1.0//EN", "/dtd/svg10.dtd");
    companion object {
        fun match(publicId: String?): SvgDtdWhitelist? =
            values().firstOrNull { it.publicId == publicId }
    }
}

// 所有外部实体解析请求必须经过该解析器：非白名单一律返回空源
class SvgEntityResolver : EntityResolver {
    override fun resolveEntity(publicId: String?, systemId: String?): InputSource {
        val trusted = SvgDtdWhitelist.match(publicId)
            ?: return InputSource(CharArrayReader(CharArray(0))) // 拒绝：不发起任何网络或文件访问
        return InputSource(javaClass.getResourceAsStream(trusted.localResource))
    }
}

fun readSvgSizeForRasterizer(svgBytes: ByteArray): Pair<Float, Float> {
    val factory = DocumentBuilderFactory.newInstance()
    factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true)
    factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", false) // 表面危险：保留 DTD 处理
    factory.isExpandEntityReferences = false
    val builder = factory.newDocumentBuilder()
    builder.setEntityResolver(SvgEntityResolver()) // 真实防御：白名单解析器拦截全部外部实体解析
    val doc = builder.parse(svgBytes.inputStream())
    val root = doc.documentElement
    return Pair(root.getAttribute("width").toFloat(), root.getAttribute("height").toFloat())
}
