import java.security.SecureRandom
import java.util.Base64
import java.util.Random

// 数据同步工作线程：向服务端上报批次并携带一次性同步令牌
class DataSyncWorker(private val endpoint: String) {

    private val jitterRng = Random()      // 表面危险源：非安全随机 API
    private val tokenRng = SecureRandom() // 防御点：语言原生 CSPRNG

    // 表面危险：java.util.Random 常被标记为 CWE-330 危险模式
    fun nextRetryDelayMillis(attempt: Int): Long =
        attempt * 1_000L + jitterRng.nextInt(250)

    fun newSyncToken(): String {
        val raw = ByteArray(32)
        tokenRng.nextBytes(raw)
        return Base64.getEncoder().encodeToString(raw)
    }

    fun runSyncCycle(attempt: Int) {
        Thread.sleep(nextRetryDelayMillis(attempt))
        val token = newSyncToken()
        // 令牌仅经内存传给网络层，不落日志、不由时间戳派生
        upload(endpoint, token)
    }

    private fun upload(url: String, token: String): Boolean {
        println("POST $url tokenLen=${token.length}")
        return true
    }
}
