package com.intranet.richtext

import java.io.ByteArrayInputStream
import java.io.ObjectInputFilter
import java.io.ObjectInputFilter.Status
import java.io.ObjectInputStream
import java.sql.Connection
import java.sql.PreparedStatement
import java.util.Base64

data class RichTextDoc(val title: String, val bodyHtml: String) : java.io.Serializable {
    companion object { private const val serialVersionUID: Long = 1L }
}

object RichTextImporter {
    // 防御核心：JEP 290 反序列化白名单过滤器，仅放行业务文档类与基础类型
    private val docFilter = ObjectInputFilter { info ->
        val cls = info.serialClass()
        when {
            info.streamBytes() > 1_048_576L || info.depth() > 50 || info.references() > 2000 -> Status.REJECTED
            cls == null -> Status.UNDECIDED
            cls == RichTextDoc::class.java || cls == String::class.java || cls == Integer::class.java -> Status.ALLOWED
            else -> Status.REJECTED
        }
    }

    fun importDoc(serializedB64: ByteArray, conn: Connection): Boolean {
        val bytes = Base64.getDecoder().decode(serializedB64)
        val doc = ByteArrayInputStream(bytes).use { input ->
            ObjectInputStream(input).use { ois ->
                ois.setObjectInputFilter(docFilter)
                ois.readObject() as? RichTextDoc
            }
        } ?: return false
        conn.prepareStatement("INSERT INTO rich_text_docs(title, body_html) VALUES (?, ?)").use { ps ->
            ps.setString(1, doc.title)
            ps.setString(2, doc.bodyHtml)
            ps.executeUpdate()
        }
        return true
    }
}
