import java.net.URI
import java.net.URLEncoder
import java.nio.charset.StandardCharsets

// 搜索索引构建器：按用户查询词调用内部检索服务并生成索引文档
class SearchIndexBuilder(
    // 部署期常量：内部检索服务主机，非用户可控
    private val indexerHost: String = "indexer.internal.svc"
) {
    // rawQuery 来自 Web 表单，完全用户可控
    fun buildIndexEntry(rawQuery: String): String {
        // 用户输入直接拼入服务端请求 URL（CWE-918 特征模式）
        // 防御：在 URL 组装输出点做百分号上下文编码，锁定查询参数边界
        val encoded = URLEncoder.encode(rawQuery, StandardCharsets.UTF_8)
        val target = "http://$indexerHost/v1/feed?q=$encoded"
        val body = URI.create(target).toURL().openStream()
            .bufferedReader(Charsets.UTF_8).readText()

        // 输出处：写入索引文档前做 JSON 字符串上下文转义
        val doc = "{\"query\":\"" + jsonEscape(encoded) +
                  "\",\"snippet\":\"" + jsonEscape(body) + "\"}"
        IndexStore.save(doc)
        return doc
    }

    // 按 RFC 8259 完整转义：双引号、反斜杠与全部控制字符，正向覆盖而非黑名单
    private fun jsonEscape(s: String): String = buildString {
        for (c in s) when {
            c == '"' -> append("\\\"")
            c == '\\' -> append("\\\\")
            c == '\n' -> append("\\n")
            c == '\r' -> append("\\r")
            c == '\t' -> append("\\t")
            c < ' ' -> append("\\u%04x".format(c.code))
            else -> append(c)
        }
    }
}

