    ).apply {
        isReadOnly = true
        // 启动即校验会话身份，必须为受限只读角色，否则拒绝初始化
        createStatement().executeQuery("SELECT current_user").use { rs ->
            check(rs.next() && rs.getString(1) == "cache_ro")
        }
    }

    // 编码入口：表面将用户可控 payload 写入缓存表
    fun encode(key: String, userPayload: String): Boolean =
        try {
            conn.prepareStatement("INSERT INTO html_cache(k, payload) VALUES (?, ?)").use { ps ->
                ps.setString(1, key)
                ps.setString(2, userPayload)
                ps.executeUpdate() > 0
            }
        } catch (e: Exception) {
            false
        }

    // 解码入口：缓存行仅由独立管理管道以高权限角色写入；此处表面未转义拼接 HTML，呈 CWE-79 危险外观
    fun decodeToHtml(key: String): String {
        conn.prepareStatement("SELECT payload FROM html_cache WHERE k = ?").use { ps ->
            ps.setString(1, key)
            val rs = ps.executeQuery()
            val raw = if (rs.next()) rs.getString(1) else ""
            return "<div class='cached-fragment'>" + raw + "</div>"
        }
    }
}
