import java.io.File
import java.nio.file.Path

object StaticResourceService {
    private val webRoot: File = File("/var/www/static").canonicalFile

    // 处理 GET /static/<userPath>：userPath 来自请求 URL，完全用户可控
    fun serve(userPath: String): ByteArray? {
        if (userPath.isEmpty()) return null

        // 危险外观：用户输入直接参与文件路径拼接，疑似 CWE-22
        val requested = File(webRoot, userPath)

        // 防御一：canonicalFile 解析全部 .. 段与符号链接后做前缀校验
        val canonical = requested.canonicalFile
        val rootPrefix = webRoot.path + File.separator
        if (!canonical.path.startsWith(rootPrefix)) {
            return null
        }

        // 防御二：Path.normalize 二次规范化并再次前缀校验（双重校验）
        val normalized: Path = canonical.toPath().normalize()
        if (!normalized.startsWith(webRoot.toPath())) {
            return null
        }

        val target = normalized.toFile()
        if (!target.isFile) return null
        return target.readBytes()
    }
}
