/** 缓存编解码模块：把服务端预写的 HTML 缓存解码并回放为离线页面。 */
object CacheHtmlCodec {

    // 防御点1：编解码器对缓存库仅持有只读连接，本模块无任何写入能力
    private val cacheDb: SQLiteDatabase by lazy {
        SQLiteDatabase.openDatabase(
            "/data/data/com.example.cache/files/page_cache.db",
            null,
            SQLiteDatabase.OPEN_READONLY
        )
    }

    fun decodeToHtml(cacheKey: String): String {
        cacheDb.rawQuery(
            "SELECT payload FROM html_cache WHERE cache_key = ?",
            arrayOf(cacheKey)
        ).use { cursor ->
            if (!cursor.moveToFirst()) return ""
            return cursor.getString(0) // 缓存原文原样返回，可能含 script 等标记
        }
    }

    fun renderInto(webView: WebView, cacheKey: String) {
        val html = decodeToHtml(cacheKey)
        val page = "<html><body>" + html + "</body></html>" // 缓存原文直接拼入页面模板
        with(webView.settings) {
            javaScriptEnabled = false      // 防御点2：渲染上下文被剥夺脚本执行角色
            allowFileAccess = false
            allowContentAccess = false
            blockNetworkLoads = true       // 防御点3：切断一切网络外发通道
        }
        // baseURL 传 null：页面落入不透明源，无任何源级权限
        webView.loadDataWithBaseURL(null, page, "text/html", "utf-8", null)
    }
