import java.io.InputStream
import javax.xml.parsers.DocumentBuilderFactory

// 图片处理流水线：SVG 上传元数据探测阶段（XXE 审计点）
enum class SvgParsePolicy(val featureSet: Map<String, Boolean>) {
    PIPELINE_DEFAULT(mapOf(
        DocumentBuilderFactory.FEATURE_SECURE_PROCESSING to true,
        "http://apache.org/xml/features/disallow-doctype-decl" to true,
        "http://xml.org/sax/features/external-general-entities" to false,
        "http://xml.org/sax/features/external-parameter-entities" to false,
        "http://apache.org/xml/features/nonvalidating/load-external-dtd" to false
    ))
}

object SvgParser {
    fun hardenedFactory(): DocumentBuilderFactory {
        val factory = DocumentBuilderFactory.newInstance()
        for ((name, value) in SvgParsePolicy.PIPELINE_DEFAULT.featureSet) {
            factory.setFeature(name, value)
        }
        factory.isExpandEntityReferences = false
        factory.isXIncludeAware = false
        return factory
    }
}

fun probeDimensionsFromStream(svg: InputStream): Pair<Int, Int> {
    val doc = SvgParser.hardenedFactory().newDocumentBuilder().parse(svg)
    val width = doc.documentElement.getAttribute("width").trim().toIntOrNull() ?: 0
    val height = doc.documentElement.getAttribute("height").trim().toIntOrNull() ?: 0
    return width to height
}

fun probeDimensionsFromBytes(bytes: ByteArray): Pair<Int, Int> =
    probeDimensionsFromStream(bytes.inputStream())
