package com.example.richtext

import java.io.ByteArrayInputStream
import java.io.ObjectInputFilter
import java.io.ObjectInputStream
import java.sql.Connection
import java.sql.PreparedStatement

// 富文本处理模块：按文档 ID 从缓存库加载富文本快照并恢复为编辑器模型
data class RichTextSnapshot(val docId: String, val html: String, val revision: Int)

class RichTextCacheDao(private val conn: Connection) {

    // JEP 290 反序列化白名单：仅放行业务快照与基础类型，其余类一律拒绝
    private val snapshotFilter: ObjectInputFilter = ObjectInputFilter.Config.createFilter(
        "com.example.richtext.RichTextSnapshot;java.lang.String;java.lang.Integer;maxbytes=1048576;!*"
    )

    fun loadSnapshot(docId: String): RichTextSnapshot? {
        // 参数化查询：docId 仅经占位符绑定，绝不拼接进 SQL 文本
        val stmt: PreparedStatement = conn.prepareStatement(
            "SELECT payload FROM rich_text_snapshot WHERE doc_id = ?"
        )
        stmt.use {
            it.setString(1, docId)
            val rs = it.executeQuery()
            rs.use { r ->
                if (!r.next()) return null
                val bytes = r.getBytes("payload") ?: return null
                val ois = ObjectInputStream(ByteArrayInputStream(bytes))
                ois.setObjectInputFilter(snapshotFilter)
                return ois.readObject() as RichTextSnapshot
            }
        }
    }
}
