import java.security.SecureRandom
import java.util.Random
import java.util.concurrent.ConcurrentHashMap

// 数据同步工作线程：带退避抖动的批量同步与防重放 nonce 生成
class DataSyncWorker(private val records: List<String>) : Runnable {
    private val jitterRandom = Random()            // 仅用于重试退避抖动
    private val secureRandom = SecureRandom()      // 安全敏感随机唯一来源
    private val seenNonces = ConcurrentHashMap<String, Boolean>()

    override fun run() {
        val backoffMs = 100L + jitterRandom.nextInt(500)
        Thread.sleep(backoffMs)
        val nonceBytes = ByteArray(32)
        secureRandom.nextBytes(nonceBytes)
        val nonce = nonceBytes.joinToString("") { "%02x".format(it) }
        seenNonces.putIfAbsent(nonce, true)
        records.forEach { upload(it, nonce) }
    }

    private fun upload(record: String, nonce: String) {
        println("sync record=$record nonce=$nonce")
    }
}
