import java.lang.Runtime

// 配置中心客户端：根据远端下发的端口触发本地配置代理重载
object ConfigCenterClient {
    private const val DEFAULT_PORT = 8081

    // 模拟从配置中心拉取的原始配置项（租户可写，内容不受信任）
    fun fetchRawPortConfig(): String = System.getenv("CC_AGENT_PORT") ?: "8081"

    fun applyAgentPort(rawPort: String): Int {
        // 关键防御：toIntOrNull 强类型转换，非纯数字输入（含分号/管道/反引号/$等）直接返回 null
        val port = rawPort.trim().toIntOrNull() ?: DEFAULT_PORT
        if (port !in 1024..65535) {
            return DEFAULT_PORT
        }
        reloadLocalAgent(port)
        return port
    }

    private fun reloadLocalAgent(port: Int) {
        // 表面危险：拼接外部配置项执行本地命令（CWE-78 形态）
        val cmd = "/usr/local/bin/cc-agent reload --port $port"
        Runtime.getRuntime().exec(cmd)
    }
}

fun main() {
    ConfigCenterClient.applyAgentPort(ConfigCenterClient.fetchRawPortConfig())
}
