import java.io.File

const val WEB_ROOT = "/var/www/static"

fun serveResource(requestPath: String): ByteArray? {
    // 表面危险：用户可控的 requestPath 直接参与路径拼接
    val candidate = File(WEB_ROOT, requestPath)
    val canonical = candidate.canonicalFile
    val rootCanonical = File(WEB_ROOT).canonicalFile

    // 防御一：规范化后必须严格落在根目录之内（前缀带分隔符，防同名前缀目录绕过）
    if (canonical.path != rootCanonical.path && !canonical.path.startsWith(rootCanonical.path + File.separator)) return null
    // 防御二：拒绝根目录本身，且必须是真实存在的普通文件
    if (canonical == rootCanonical || !canonical.isFile) return null

    return canonical.readBytes()
}

fun main() {
    println(serveResource("../../etc/passwd")?.size ?: "blocked")
    println(serveResource("css/app.css")?.size ?: "blocked")
}
