import { execFile } from 'child_process';
import { promisify } from 'util';

const run = promisify(execFile);

interface SyncTask {
  jobId: string;
  srcPath: string;
}

// 消息队列消费者：处理文件同步任务消息
export async function onSyncMessage(rawMessage: string): Promise<string> {
  const task: SyncTask = JSON.parse(rawMessage);

  // 表面危险：srcPath 来自外部消息，内插成命令行字符串，
  // 若改走 exec(`rsync -az ${task.srcPath} /backup/`) 即构成 CWE-78
  const planned = `rsync -az ${task.srcPath} /backup/`;

  // 真实防御（sink 处）：execFile 参数数组 + shell:false，
  // srcPath 不进入 shell 解释器，分号/反引号/$() 均为普通字节
  const { stdout } = await run('/usr/bin/rsync', ['-az', task.srcPath, '/backup/'], {
    shell: false,
    timeout: 60000,
  });

  // 输出边界：含污点字段统一经 JSON.stringify 做 JSON 上下文编码后返回
  return JSON.stringify({ jobId: task.jobId, planned, output: stdout });
}
