using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;

namespace Gateway
{
    // 白名单枚举：仅收录网关允许的强算法，MD5/SHA1 不在集合内
    public enum ForwardSignAlgorithm { HmacSha256, HmacSha384, HmacSha512 }

    public static class AlgorithmRegistry
    {
        private static readonly Dictionary<ForwardSignAlgorithm, Func<HMAC>> Registry =
            new Dictionary<ForwardSignAlgorithm, Func<HMAC>>
            {
                { ForwardSignAlgorithm.HmacSha256, () => new HMACSHA256() },
                { ForwardSignAlgorithm.HmacSha384, () => new HMACSHA384() },
                { ForwardSignAlgorithm.HmacSha512, () => new HMACSHA512() }
            };
        public static HMAC Resolve(ForwardSignAlgorithm alg)
        {
            Func<HMAC> factory;
            if (!Registry.TryGetValue(alg, out factory))
                throw new NotSupportedException("algorithm not allowed");
            return factory();
        }
    }

    public class ApiGatewayForwarder
    {
        // requestedAlgorithm 来自外部转发请求头，仅允许白名单强算法
        public byte[] SignForForward(string requestedAlgorithm, string payload, byte[] signingKey)
        {
            ForwardSignAlgorithm alg;
            if (!Enum.TryParse(requestedAlgorithm, false, out alg)
                || !Enum.IsDefined(typeof(ForwardSignAlgorithm), alg))
                throw new ArgumentException("unsupported algorithm");
            using (HMAC hmac = AlgorithmRegistry.Resolve(alg))
            {
                hmac.Key = signingKey;
                return hmac.ComputeHash(Encoding.UTF8.GetBytes(payload));
            }
        }
    }
}
