import java.io.File
import java.nio.file.Paths

private const val WEB_ROOT = "/var/www/static"

// 静态资源服务：仅允许读取 WEB_ROOT 目录树内的文件
fun serveStaticResource(rawRequestPath: String): ByteArray? {
    // 入口过滤：拒绝空字节与反斜杠混淆
    if (rawRequestPath.contains('\u0000') || rawRequestPath.contains('\\')) return null

    val rootDir = File(WEB_ROOT).canonicalFile
    val requested = File(rootDir, rawRequestPath.trimStart('/')).canonicalFile

    // 防御一：canonical 字符串前缀校验，补分隔符防同名前缀误放行
    val rootPrefix = rootDir.canonicalPath + File.separator
    // 防御二：Path 组件级前缀校验，与防御一构成双重独立验证
    val rootPath = Paths.get(rootDir.canonicalPath)
    val reqPath = Paths.get(requested.canonicalPath)

    if (!requested.canonicalPath.startsWith(rootPrefix)) return null
    if (!reqPath.startsWith(rootPath)) return null

    if (!requested.isFile || !requested.canRead()) return null
    return requested.readBytes()
}
