using System;
using System.Security.Cryptography;

namespace ApiGateway.Forward
{
    // 转发签名策略白名单：精确允许集，仅含 SHA-2 家族三个成员，弱算法无对应成员
    internal enum ForwardHashPolicy
    {
        Sha256,
        Sha384,
        Sha512
    }

    public static class ForwardSigner
    {
        // 白名单映射：枚举成员到规范算法名的穷举映射，default 分支拒绝一切未列名值
        private static string MapToCanonical(ForwardHashPolicy policy)
        {
            switch (policy)
            {
                case ForwardHashPolicy.Sha256: return "SHA256";
                case ForwardHashPolicy.Sha384: return "SHA384";
                case ForwardHashPolicy.Sha512: return "SHA512";
                default: throw new ArgumentOutOfRangeException(nameof(policy), "policy outside allow-list");
            }
        }

        // 网关转发前对请求体计算完整性签名；表面危险：requestedAlg 来自转发请求头，动态决定哈希算法，疑似 CWE-327 降级入口
        public static byte[] SignForwardBody(string requestedAlg, byte[] body)
        {
            ForwardHashPolicy policy;
            if (string.IsNullOrEmpty(requestedAlg) ||
                !Enum.TryParse(requestedAlg, ignoreCase: false, out policy) ||
                !Enum.IsDefined(typeof(ForwardHashPolicy), policy))
            {
                throw new ArgumentException("requestedAlg not in allow-list");
            }
            string canonical = MapToCanonical(policy);
            using (HashAlgorithm hasher = HashAlgorithm.Create(canonical))
            {
                return hasher.ComputeHash(body);
            }
        }
    }
}
